            const material = createMaterial({
                enableGGXSpecular: false,
                anisotropyIntensity: 1,
                anisotropyRotation: 45
            });

            const { output, json } = writeMaterial(material);

            expect(output.extensions).toBeUndefined();
            expect(json.extensionsUsed).toBeUndefined();
        });
    });

    describe('KHR_materials_clearcoat', () => {
        test('writes the clearcoat factor, roughness, and all clearcoat textures', () => {
            const clearCoatTexture = { name: 'clearcoat' };
            const clearCoatGlossTexture = { name: 'clearcoat-gloss' };
            const clearCoatNormalTexture = { name: 'clearcoat-normal' };
            const material = createMaterial({
                clearCoat: 0.1,
                clearCoatGloss: 0.3,
                clearCoatBumpiness: 0.5,
                clearCoatMap: clearCoatTexture,
                clearCoatGlossMap: clearCoatGlossTexture,
                clearCoatNormalMap: clearCoatNormalTexture
            });

            const { output, json } = writeMaterial(material, [
                clearCoatTexture,
                clearCoatGlossTexture,
                clearCoatNormalTexture
            ]);

            expect(output.extensions.KHR_materials_clearcoat).toEqual({
                clearcoatFactor: 0.4,
                clearcoatRoughnessFactor: 0.3,
                clearcoatTexture: { index: 0 },
                clearcoatRoughnessTexture: { index: 1 },
                clearcoatNormalTexture: {
                    index: 2,
                    scale: 0.5
                }
            });
            expect(json.extensionsUsed).toEqual(['KHR_materials_clearcoat']);
        });

        test('clamps the clearcoat factor to one and omits default optional fields', () => {
            const material = createMaterial({
                clearCoat: 0.8,
                clearCoatGloss: 0,
                clearCoatBumpiness: 1
            });

            const { output } = writeMaterial(material);

            expect(output.extensions.KHR_materials_clearcoat).toEqual({
                clearcoatFactor: 1
            });
        });

        test('does not write clearcoat when its factor is zero', () => {
            const material = createMaterial({
                clearCoat: 0,
                clearCoatGloss: 0.5,
                clearCoatMap: { name: 'clearcoat' }
            });

            const { output } = writeMaterial(material, [material.clearCoatMap]);

            expect(output.extensions).toBeUndefined();
        });
    });

    describe('scalar material extensions', () => {
        test('writes KHR_materials_dispersion for a non-zero dispersion', () => {
            const { output, json } = writeMaterial(createMaterial({ dispersion: 0.2 }));

            expect(output.extensions).toEqual({
                KHR_materials_dispersion: {
                    dispersion: 0.2
                }
            });
            expect(json.extensionsUsed).toEqual(['KHR_materials_dispersion']);
        });

        test('writes KHR_materials_ior as the reciprocal of a non-default positive refraction index', () => {
            const { output, json } = writeMaterial(createMaterial({ refractionIndex: 0.5 }));

            expect(output.extensions).toEqual({
                KHR_materials_ior: {
                    ior: 2
                }
            });
            expect(json.extensionsUsed).toEqual(['KHR_materials_ior']);
        });

        test('omits KHR_materials_ior for the default and non-positive refraction indices', () => {
            const defaultResult = writeMaterial(createMaterial({ refractionIndex: DEFAULT_IOR }));
            const zeroResult = writeMaterial(createMaterial({ refractionIndex: 0 }));

            expect(defaultResult.output.extensions).toBeUndefined();
            expect(zeroResult.output.extensions).toBeUndefined();
        });
    });

