            const iridescenceTexture = { name: 'iridescence' };
            const thicknessTexture = { name: 'iridescence-thickness' };
            const material = createMaterial({
                useIridescence: true,
                iridescence: 0.4,
                iridescenceRefractionIndex: 1.4,
                iridescenceThicknessMin: 120,
                iridescenceThicknessMax: 500,
                iridescenceMap: iridescenceTexture,
                iridescenceThicknessMap: thicknessTexture
            });

            const { output, json } = writeMaterial(material, [iridescenceTexture, thicknessTexture]);

            expect(output.extensions.KHR_materials_iridescence).toEqual({
                iridescenceFactor: 0.4,
                iridescenceIor: 1.4,
                iridescenceThicknessMinimum: 120,
                iridescenceThicknessMaximum: 500,
                iridescenceTexture: { index: 0 },
                iridescenceThicknessTexture: { index: 1 }
            });
            expect(json.extensionsUsed).toEqual(['KHR_materials_iridescence']);
        });

        test('omits the extension when iridescence is enabled with entirely default values', () => {
            const { output, json } = writeMaterial(createMaterial({ useIridescence: true }));

            expect(output.extensions).toBeUndefined();
            expect(json.extensionsUsed).toBeUndefined();
        });

        test('does not write iridescence when it is disabled even if properties are non-default', () => {
            const { output } = writeMaterial(createMaterial({
                useIridescence: false,
                iridescence: 0.8,
                iridescenceMap: { name: 'iridescence' }
            }));

            expect(output.extensions).toBeUndefined();
        });
    });

