        test('writes a linearized sheen color, roughness, and textures', () => {
            const sheenTexture = { name: 'sheen' };
            const sheenGlossTexture = { name: 'sheen-gloss' };
            const material = createMaterial({
                useSheen: true,
                sheen: new Color(0.5, 0.25, 0.1, 1),
                sheenGloss: 0.6,
                sheenMap: sheenTexture,
                sheenGlossMap: sheenGlossTexture
            });

            const { output, json } = writeMaterial(material, [sheenTexture, sheenGlossTexture]);

            const sheenExt = output.extensions.KHR_materials_sheen;
            expectColorFactor(sheenExt.sheenColorFactor, [
                Math.pow(0.5, 2.2),
                Math.pow(0.25, 2.2),
                Math.pow(0.1, 2.2)
            ]);
            expect(sheenExt.sheenRoughnessFactor).toBe(0.6);
            expect(sheenExt.sheenColorTexture).toEqual({ index: 0 });
            expect(sheenExt.sheenRoughnessTexture).toEqual({ index: 1 });
            expect(json.extensionsUsed).toEqual(['KHR_materials_sheen']);
        });

        test('omits sheen when enabled with default black color and zero gloss', () => {
            const { output } = writeMaterial(createMaterial({ useSheen: true }));

            expect(output.extensions).toBeUndefined();
        });

