                specularityFactor: 0.6,
                specularMap: specularTexture,
                specularityFactorMap: specularityTexture
            });

            const { output, json } = writeMaterial(material, [specularTexture, specularityTexture]);

            const specularExt = output.extensions.KHR_materials_specular;
            expectColorFactor(specularExt.specularColorFactor, [
                Math.pow(0.5, 2.2),
                Math.pow(0.25, 2.2),
                Math.pow(0.1, 2.2)
            ]);
            expect(specularExt.specularFactor).toBe(0.6);
            expect(specularExt.specularColorTexture).toEqual({ index: 0 });
            expect(specularExt.specularTexture).toEqual({ index: 1 });
            expect(json.extensionsUsed).toEqual(['KHR_materials_specular']);
        });

        test('writes the specular extension for spec-gloss materials', () => {
            const material = createMaterial({
                useMetalness: false,
                specularityFactor: 0.5
            });

            const { output } = writeMaterial(material);

            expect(output.pbrMetallicRoughness.metallicFactor).toBe(0);
            expect(output.extensions.KHR_materials_specular).toEqual({
                specularFactor: 0.5
            });
        });

        test('does not write specular for metallic materials without specular color tint', () => {
            const material = createMaterial({
                useMetalness: true,
                useMetalnessSpecularColor: false,
                specular: new Color(0, 0, 0, 1),
                specularityFactor: 0.2
            });

            const { output } = writeMaterial(material);

            expect(output.extensions).toBeUndefined();
        });
    });

