            const refractionTexture = { name: 'refraction' };
            const material = createMaterial({
                useDynamicRefraction: true,
                refraction: 0.75,
                refractionMap: refractionTexture
            });

            const { output, json } = writeMaterial(material, [refractionTexture]);

            expect(output.extensions.KHR_materials_transmission).toEqual({
                transmissionFactor: 0.75,
                transmissionTexture: { index: 0 }
            });
            expect(json.extensionsUsed).toEqual(['KHR_materials_transmission']);
        });

        test('writes a texture-only transmission extension when only a refraction map is set', () => {
            const refractionTexture = { name: 'refraction' };
            const material = createMaterial({
                useDynamicRefraction: true,
