import { GltfExporter } from '../../../../src/extras/exporters/gltf-exporter.js';

const DEFAULT_IOR = 1 / 1.5;

function createMaterial(overrides = {}) {
    return {
        useLighting: true,
        diffuse: new Color(1, 1, 1, 1),
        emissive: new Color(0, 0, 0, 1),
        opacity: 1,
        useMetalness: true,
        metalness: 1,
        gloss: 0,
        glossInvert: false,

        enableGGXSpecular: false,
        anisotropyIntensity: 0,
        anisotropyRotation: 0,

        clearCoat: 0,
        clearCoatGloss: 0,
        clearCoatBumpiness: 1,

        dispersion: 0,
        emissiveIntensity: 1,
        refractionIndex: DEFAULT_IOR,

        useIridescence: false,
        iridescence: 0,
        iridescenceRefractionIndex: 1.3,
        iridescenceThicknessMin: 100,
        iridescenceThicknessMax: 400,

        useSheen: false,
        sheen: new Color(0, 0, 0, 1),
        sheenGloss: 0,

        useMetalnessSpecularColor: false,
        specular: new Color(1, 1, 1, 1),
        specularityFactor: 1,

        useDynamicRefraction: false,
        refraction: 0,
        thickness: 0,
        attenuationDistance: 0,
        attenuation: new Color(1, 1, 1, 1),

        ...overrides
    };
}

function writeMaterial(material, textures = []) {
    // StandardMaterial initializes each texture's rotation to zero. Supply the same
    // defaults on the test doubles so attachTexture does not treat undefined as a
    // non-default rotation.
    Object.keys(material).forEach((key) => {
        if (key.endsWith('Map') && material[key] && material[`${key}Rotation`] === undefined) {
            material[`${key}Rotation`] = 0;
        }
    });

    const exporter = new GltfExporter();
    const resources = { textures };
    const output = {
        pbrMetallicRoughness: {}
    };
    const json = {};

    exporter.writeStandardMaterial(resources, material, output, json);

    return { output, json };
}

function expectColorFactor(actual, expected) {
    expect(actual).toHaveLength(expected.length);
    expected.forEach((value, index) => {
        expect(actual[index]).toBeCloseTo(value, 10);
    });
}

describe('GltfExporter#writeStandardMaterial', () => {
    describe('PBR metallic-roughness factors', () => {
        test('omits all optional factors for a default lit metallic material', () => {
            const { output, json } = writeMaterial(createMaterial());

            expect(output).toEqual({
                pbrMetallicRoughness: {}
            });
            expect(json).toEqual({});
        });

        test('writes a linearized baseColorFactor from a non-white diffuse color and opacity', () => {
            const material = createMaterial({
                diffuse: new Color(0.5, 0.25, 0.1, 1),
                opacity: 0.4
            });

            const { output } = writeMaterial(material);

            expectColorFactor(output.pbrMetallicRoughness.baseColorFactor, [
                Math.pow(0.5, 2.2),
                Math.pow(0.25, 2.2),
                Math.pow(0.1, 2.2),
                0.4
            ]);
        });

        test('writes baseColorFactor when the diffuse color is white but opacity is not one', () => {
            const { output } = writeMaterial(createMaterial({ opacity: 0.25 }));

            expectColorFactor(output.pbrMetallicRoughness.baseColorFactor, [1, 1, 1, 0.25]);
        });

        test('uses the emissive color as the unlit base color source', () => {
            const material = createMaterial({
                useLighting: false,
                diffuse: new Color(1, 1, 1, 1),
                emissive: new Color(0.2, 0.4, 0.6, 1)
            });

            const { output, json } = writeMaterial(material);

            expectColorFactor(output.pbrMetallicRoughness.baseColorFactor, [
                Math.pow(0.2, 2.2),
                Math.pow(0.4, 2.2),
                Math.pow(0.6, 2.2),
                1
            ]);
            expect(output.emissiveFactor).toBeUndefined();

    describe('KHR_materials_volume', () => {
        test('writes thickness, attenuation, and texture when dynamic refraction is enabled', () => {
            const thicknessTexture = { name: 'thickness' };
            const material = createMaterial({
                useDynamicRefraction: true,
                thickness: 0.5,
                attenuationDistance: 2,
                attenuation: new Color(0.5, 0.25, 0.1, 1),
                thicknessMap: thicknessTexture
            });

            const { output, json } = writeMaterial(material, [thicknessTexture]);

            const volumeExt = output.extensions.KHR_materials_volume;
            expect(volumeExt.thicknessFactor).toBe(0.5);
            expect(volumeExt.attenuationDistance).toBe(2);
            expectColorFactor(volumeExt.attenuationColor, [
                Math.pow(0.5, 2.2),
                Math.pow(0.25, 2.2),
                Math.pow(0.1, 2.2)
            ]);
            expect(volumeExt.thicknessTexture).toEqual({ index: 0 });
            expect(json.extensionsUsed).toEqual(['KHR_materials_volume']);
        });

        test('does not write volume when dynamic refraction is enabled but volume values are default', () => {
            const material = createMaterial({
                useDynamicRefraction: true,
                thickness: 0,
                attenuationDistance: 0,
                attenuation: new Color(1, 1, 1, 1)
            });

            const { output } = writeMaterial(material);

            expect(output.extensions).toBeUndefined();
        });
    });
});

