                }
            } else {
                view.transformPoint(_position, _viewPosition);
                inFront = _viewPosition.z < 0;
                _clip.set(_position.x, _position.y, _position.z, 1);
            }
            _viewProj.transformVec4(_clip, _clip);

            let x = 0;
            let y = 0;
            let onScreen = -1;
