            const effect = createEffect();
            const light = createLight({
                type: 'directional',
                color: new Color(0.5, 0.5, 0.5)
            });
            const flare = new LensFlare(null, { light });
            flare.useLightIntensity = false;
            flare.useLightColor = false;

            update(effect, [flare]);

            expect(dataAt(effect, 0).r).toBeCloseTo(1, 6);
