            const flares = [];
            for (let i = 0; i < LENSFLARE_MAX_FLARES + 1; i++) {
                // every flare resolves to a distinct screen position
                flares.push(new LensFlare(null, { position: new Vec3(i + 1, 0, -10) }));
            }

