            update(effect, flares);

            const last = dataAt(effect, LENSFLARE_MAX_FLARES - 1);
            expect(last.x).toBeCloseTo(LENSFLARE_MAX_FLARES / 10, 6);
            expect(last.fade).toBe(1);
