            expect(data.onScreen).toBe(1);
            expect(data.scale).toBe(3);
            expect(data.r).toBe(2);
            expect(data.g).toBe(1);
            expect(data.b).toBe(0.5);
            expect(data.depth).toBeCloseTo(10, 6);
            expect(data.occlusionRadius).toBe(0.02);
        });

        it('writes the flares in the order they are registered', () => {
