                position: new Vec3(0, 0, -10),
                outerConeAngle: 30,
                innerConeAngle: 20
            });
            const flare = new LensFlare(null, { light });

            update(effect, [flare]);

            const fade = dataAt(effect, 0).fade;
            expect(fade).toBeGreaterThan(0);
            expect(fade).toBeLessThan(1);
        });

