            const flare = new LensFlare(null, { direction: new Vec3(1, 0, -2) });

            // for a perspective projection the direction is a vanishing point at the edge of the
            // screen, whereas for an orthographic one it is a position far along the direction
            const perspective = createEffect(createCameraComponent());
            update(perspective, [flare]);
            expect(dataAt(perspective, 0).x).toBeCloseTo(0.5, 6);
            expect(dataAt(perspective, 0).onScreen).toBe(1);

            const orthographic = createEffect(createCameraComponent({ orthographic: true }));
            update(orthographic, [flare]);
            expect(dataAt(orthographic, 0).x).toBeGreaterThan(1);
            expect(dataAt(orthographic, 0).onScreen).toBe(0);
            expect(dataAt(orthographic, 0).fade).toBe(0);
            expect(dataAt(orthographic, 0).depth).toBeCloseTo(FAR * DIRECTIONAL_DEPTH, 6);
        });

        it('divides a positional source by the clip space w for an orthographic projection', () => {
            const effect = createEffect(createCameraComponent({ orthographic: true }));
            // the orthographic frustum of the test camera is 20 units wide, so 10 units is the edge
            const flare = new LensFlare(null, { position: new Vec3(2, -4, -10) });

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            expect(data.x).toBeCloseTo(0.2, 6);
            expect(data.y).toBeCloseTo(-0.4, 6);
            expect(data.fade).toBe(1);
            expect(data.depth).toBeCloseTo(10, 6);
        });

        it('fades a source out at the edge of the screen', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(9, 0, -10) });
            flare.edgeFade = 0.2;
            flare.allowOffScreen = false;

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            // half way through the fade band which starts at 0.8 of half the screen size
            expect(data.x).toBeCloseTo(0.9, 6);
            expect(data.fade).toBeCloseTo(0.5, 6);
            expect(data.onScreen).toBe(1);
        });

        it('stops drawing a source at the edge of the screen when off screen flares are not allowed', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(10, 0, -10) });
            flare.edgeFade = 0.2;
            flare.allowOffScreen = false;

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            expect(data.x).toBeCloseTo(1, 6);
            expect(data.fade).toBe(0);
            expect(data.onScreen).toBe(1);
        });

        it('keeps drawing a source beyond the edge of the screen when off screen flares are allowed', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(10, 0, -10) });
            flare.edgeFade = 0.2;
            flare.allowOffScreen = true;

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            expect(data.x).toBeCloseTo(1, 6);
            expect(data.fade).toBeCloseTo(0.5, 6);
            // the source is outside the screen, but the flare is still drawn
            expect(data.onScreen).toBe(0);
        });

        it('stops drawing a source far outside the screen', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(20, 0, -10) });
            flare.edgeFade = 0.2;
            flare.allowOffScreen = true;

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            expect(data.x).toBeCloseTo(2, 6);
            expect(data.fade).toBe(0);
            expect(data.onScreen).toBe(0);
        });

