            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(9, 0, -10) });
            flare.edgeFade = -0.5;
            flare.allowOffScreen = false;

            update(effect, [flare]);

            expect(dataAt(effect, 0).fade).toBe(1);
            expect(dataAt(effect, 0).onScreen).toBe(1);
        });

