            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.fadeStart = 5;
            flare.fadeEnd = 15;

            update(effect, [flare]);

            // the source is half way through the fade band
            expect(dataAt(effect, 0).fade).toBeCloseTo(0.5, 6);
        });

