            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.fadeStart = 5;
            flare.fadeEnd = 10;

            update(effect, [flare]);

            expect(dataAt(effect, 0).fade).toBe(0);
        });

        it('does not fade a directional source with the distance', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { direction: new Vec3(0, 0, -1) });
            flare.fadeStart = 0;
            flare.fadeEnd = 1;

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            expect(data.fade).toBe(1);
            expect(data.depth).toBeCloseTo(FAR * DIRECTIONAL_DEPTH, 6);
        });

