            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.occlusionOffset = 2;
            flare.occlusionRadius = 0.05;

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            expect(data.depth).toBeCloseTo(8, 6);
            expect(data.occlusionRadius).toBe(0.05);
        });

        it('follows the visibility immediately when the occlusion fade is zero', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.occlusionFade = 0;

            update(effect, [flare]);

            expect(dataAt(effect, 0).occlusionFade).toBe(1);
        });

        it('does not move the occlusion on the first frame', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.occlusionFade = 0.15;

            update(effect, [flare]);

            // there is no elapsed time on the first frame, as the last time is not set yet
            expect(dataAt(effect, 0).occlusionFade).toBe(0);
        });

        it('moves the occlusion by the elapsed time, clamped to a tenth of a second', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.occlusionFade = 0.15;

            update(effect, [flare]);
            // pretend the last frame was a quarter of a second ago, which the clamp limits to 0.1
            effect._lastTime -= 250;
            update(effect, [flare]);

            const expected = 1 - Math.exp(-0.1 / 0.15);
            expect(dataAt(effect, 0).occlusionFade).toBeCloseTo(expected, 4);
        });

        it('moves the occlusion by the elapsed time when it is short', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(0, 0, -10) });
            flare.occlusionFade = 0.05;

            update(effect, [flare]);
            // pretend the last frame was 50 milliseconds ago
            effect._lastTime -= 50;
            update(effect, [flare]);

            const data = dataAt(effect, 0);
            expect(data.occlusionFade).toBeGreaterThan(0.6);
            expect(data.occlusionFade).toBeLessThan(0.66);
        });

