            const effect = createEffect();
            const light = createLight({
                type: 'directional',
                intensity: 3,
                color: new Color(1, 1, 1)
            });
            const flare = new LensFlare(null, { light });
            flare.intensity = 2;
            flare.useLightColor = false;

            update(effect, [flare]);

            expect(dataAt(effect, 0).r).toBeCloseTo(6, 6);
        });

        it('ignores the intensity of the light when the flare does not use it', () => {
            const effect = createEffect();
            const light = createLight({
                type: 'directional',
                intensity: 3,
                color: new Color(1, 1, 1)
            });
            const flare = new LensFlare(null, { light });
            flare.intensity = 2;
            flare.useLightIntensity = false;
            flare.useLightColor = false;

            update(effect, [flare]);

            expect(dataAt(effect, 0).r).toBeCloseTo(2, 6);
        });

        it('scales the intensity of the flare by the luminance of its light in physical units', () => {
            const effect = createEffect(createCameraComponent({ physicalUnits: true }));
            const light = createLight({
                type: 'directional',
                lightType: LIGHTTYPE_DIRECTIONAL,
                intensity: 3,
                luminance: 5,
                color: new Color(1, 1, 1)
            });
            const flare = new LensFlare(null, { light });
            flare.intensity = 2;
            flare.useLightColor = false;

            update(effect, [flare]);

            // a directional light has a unit conversion, so the luminance scales the intensity
            expect(dataAt(effect, 0).r).toBeCloseTo(10, 6);
        });

        it('tints the colour of the flare by the linear colour of its light', () => {
            const effect = createEffect();
            const light = createLight({
                type: 'directional',
                color: new Color(0.5, 0.5, 0.5)
            });
            const flare = new LensFlare(null, { light });
            flare.useLightIntensity = false;

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            expect(data.r).toBeCloseTo(LINEAR_HALF, 5);
            expect(data.g).toBeCloseTo(LINEAR_HALF, 5);
            expect(data.b).toBeCloseTo(LINEAR_HALF, 5);
        });

        it('does not tint the colour of the flare when the light colour is not used', () => {
            const effect = createEffect();
            const light = createLight({
                type: 'directional',
                color: new Color(0.5, 0.5, 0.5)
            });
            const flare = new LensFlare(null, { light });
            flare.useLightIntensity = false;
            flare.useLightColor = false;

            update(effect, [flare]);

            expect(dataAt(effect, 0).r).toBeCloseTo(1, 6);
        });

        it('ignores the flares beyond the maximum number of flares', () => {
            const flares = [];
            for (let i = 0; i < LENSFLARE_MAX_FLARES + 1; i++) {
                // every flare resolves to a distinct screen position
                flares.push(new LensFlare(null, { position: new Vec3(i + 1, 0, -10) }));
            }

            const effect = createEffect();
            update(effect, flares);

            const last = dataAt(effect, LENSFLARE_MAX_FLARES - 1);
            expect(last.x).toBeCloseTo(LENSFLARE_MAX_FLARES / 10, 6);
            expect(last.fade).toBe(1);
            // the data of the last flare in the buffer is not overwritten by the extra one
            expect(effect._flareData.length).toBe(LENSFLARE_MAX_FLARES * 8);
            expect(effect._flareData[LENSFLARE_MAX_FLARES * 8 - 1]).toBe(0);
        });
    });
});
