        it('writes the screen position, fade, scale and colour of a positional source', () => {
            const effect = createEffect();
            const flare = new LensFlare(null, { position: new Vec3(5, 0, -10) });
            flare.intensity = 2;
            flare.color = new Color(1, 0.5, 0.25);
            flare.scale = 3;

            update(effect, [flare]);

            const data = dataAt(effect, 0);
            // the point is half way to the edge of the 90 degree frustum at a distance of 10
            expect(data.x).toBeCloseTo(0.5, 6);
            expect(data.y).toBeCloseTo(0, 6);
            expect(data.fade).toBe(1);
            expect(data.onScreen).toBe(1);
            expect(data.scale).toBe(3);
            expect(data.r).toBe(2);
            expect(data.g).toBe(1);
            expect(data.b).toBe(0.5);
            expect(data.depth).toBeCloseTo(10, 6);
            expect(data.occlusionRadius).toBeCloseTo(0.02, 6);
        });

        it('writes the flares in the order they are registered', () => {
            const effect = createEffect();
            const flares = [
                new LensFlare(null, { position: new Vec3(2, 0, -10) }),
                new LensFlare(null, { position: new Vec3(-4, 6, -9) })
            ];

            update(effect, flares);

            expect(dataAt(effect, 0).x).toBeCloseTo(0.2, 6);
            expect(dataAt(effect, 1).x).toBeCloseTo(-4 / 9, 6);
            expect(dataAt(effect, 1).y).toBeCloseTo(6 / 9, 6);
        });

        it('updates the time of the last frame', () => {
            const effect = createEffect();
            expect(effect._lastTime).toBe(0);

            update(effect, []);

            expect(effect._lastTime).toBeGreaterThan(0);
        });

