            expect(data.x).toBeCloseTo(-0.5, 6);
            expect(data.y).toBeCloseTo(0.5, 6);
            expect(data.fade).toBe(1);
...
        it('ignores the flares beyond the maximum number of flares', () => {
            const flares = [];
            for (let i = 0; i < LENSFLARE_MAX_FLARES + 1; i++) {
                // every flare resolves to a distinct position on the screen
                flares.push(new LensFlare(null, { position: new Vec3((i + 1) / 32, 0, -10) }));
            }

            const effect = createEffect();
            update(effect, flares);

            const last = dataAt(effect, LENSFLARE_MAX_FLARES - 1);
            // the 32nd flare, and not the 33rd, is the last one written
            expect(last.x).toBeCloseTo(0.1, 6);
            expect(last.fade).toBe(1);
            // the data of the last flare in the buffer is not overwritten by the extra one
            expect(effect._flareData.length).toBe(LENSFLARE_MAX_FLARES * 8);
            expect(effect._flareData[LENSFLARE_MAX_FLARES * 8 - 1]).toBe(0);
