// Properties that initializeComponentData copies from the data block onto the component.
// They are tracked so that a test can tell "not copied" apart from "copied an undefined value".
const TRACKED_PROPERTIES = [
    'width', 'height', 'enabled', 'useInput', 'fitMode', 'batchGroupId', 'layers', 'type',
    'rect', 'color', 'opacity', 'textureAsset', 'texture', 'spriteAsset', 'sprite',
