    'enableMarkup'
];

const createSystem = () => Object.create(ElementComponentSystem.prototype);

const initialize = (component, data, properties) => {
    createSystem().initializeComponentData(component, data, properties);
    return component;
};

const expectNotSet = (component, names) => {
    for (const name of names) {
        expect(component.setCalls[name]).toHaveLength(0);
    }
};

/**
 * Stand-in for ElementComponent that exposes the same writable contract used by
 * ElementComponentSystem#initializeComponentData while recording every write.
 */
class FakeElementComponent {
    constructor(options = {}) {
        const {
            anchor = new Vec4(0, 0, 0, 0),
            pivot = new Vec2(0, 0),
            calculatedWidth = 32,
            calculatedHeight = 32,
            margin = new Vec4(0, 0, -32, -32),
            position = { x: 0, y: 0, z: 0 },
            enabled = true,
            entityEnabled = true,
            parseResult = {},
            type = ELEMENTTYPE_GROUP,
            image = null
        } = options;

        this._beingInitializedValue = false;
        this.beingInitializedChanges = [];
        Object.defineProperty(this, '_beingInitialized', {
            configurable: true,
            enumerable: true,
            get: () => this._beingInitializedValue,
            set: (value) => {
                this._beingInitializedValue = value;
                this.beingInitializedChanges.push(value);
            }
        });

        this._anchor = anchor;
        this._pivot = pivot;
        this._calculatedWidth = calculatedWidth;
        this._calculatedHeight = calculatedHeight;
        this._margin = margin;

        this.anchorAssignments = [];
        Object.defineProperty(this, 'anchor', {
            configurable: true,
            enumerable: true,
            get: () => this._anchor,
            set: (value) => {
                this.anchorAssignments.push(value);
            }
        });

        this.pivotAssignments = [];
        Object.defineProperty(this, 'pivot', {
            configurable: true,
            enumerable: true,
            get: () => this._pivot,
            set: (value) => {
                this.pivotAssignments.push(value);
            }
        });

        this.marginAssignments = [];
        Object.defineProperty(this, 'margin', {
            configurable: true,
            enumerable: true,
            get: () => this._margin,
            set: (value) => {
                this.marginAssignments.push(value);
            }
        });

        this.setCalls = {};
        this.values = {};
        const initialValues = {
            enabled,
            type
        };
        for (const name of TRACKED_PROPERTIES) {
            this.setCalls[name] = [];
            this.values[name] = initialValues[name];
            Object.defineProperty(this, name, {
                configurable: true,
                enumerable: true,
                get: () => this.values[name],
                set: (value) => {
                    this.values[name] = value;
                    this.setCalls[name].push(value);
                }
            });
        }

        this.getLocalPositionCalls = [];
        const localPosition = new Vec3(position.x, position.y, position.z);
        this.entity = {
            enabled: entityEnabled,
            getLocalPosition: () => {
                this.getLocalPositionCalls.push([]);
                return localPosition;
            }
        };

        this.parseCalls = 0;
        this.parseResult = parseResult;
        this.updateScreenCalls = [];
        this.onEnableCalls = 0;

        this._image = image ?? {
            _meshDirty: false,
            mesh: {},
            _updateMesh: () => {
                throw new Error('_updateMesh should not be called by this test');
            }
        };
    }

    _parseUpToScreen() {
        this.parseCalls++;
        return this.parseResult;
    }

    _updateScreen(screen) {
        this.updateScreenCalls.push(screen);
    }

    onEnable() {
        this.onEnableCalls++;
    }
}

