/**
 * Asserts the parts of the material that every branch inherits from _createBaseImageMaterial().
 *
 * @param {StandardMaterial} material - The material returned by getImageElementMaterial().
 * @param {ElementComponentSystem} system - The system that created the material.
 */
function expectBaseImageMaterial(material, system) {
    expect(material).toBeInstanceOf(StandardMaterial);

    // the default white texture stands in for both the emissive and the opacity map
    expect(material.emissiveMap).toBe(system._defaultTexture);
    expect(material.opacityMap).toBe(system._defaultTexture);
    expect(material.opacityMapChannel).toBe('a');

    // black diffuse: the color of the element is carried entirely by the emissive term
    expect(material.diffuse.r).toBe(0);
    expect(material.diffuse.g).toBe(0);
    expect(material.diffuse.b).toBe(0);
    expect(material.emissive.r).toBe(1);
    expect(material.emissive.g).toBe(1);
    expect(material.emissive.b).toBe(1);

    expect(material.useLighting).toBe(false);
    expect(material.useTonemap).toBe(false);
    expect(material.useFog).toBe(false);
    expect(material.useSkybox).toBe(false);
    expect(material.blendType).toBe(BLEND_PREMULTIPLIED);
    expect(material.depthWrite).toBe(false);
    expect(material.getDefine('MESH_COLOR')).toBe(true);
}

/**
 * Asserts the state that a specific branch of getImageElementMaterial() applies to its material.
 *
 * @param {StandardMaterial} material - The material returned by getImageElementMaterial().
 * @param {object} expected - The expectation entry from CASES.
 */
function expectBranchState(material, expected) {
    expect(material.name).toBe(expected.name);
    expect(material.nineSlicedMode).toBe(expected.nineSlicedMode);
    expect(material.depthTest).toBe(expected.depthTest);
    expect(material.alphaTest).toBe(expected.alphaTest);
    expect(material.redWrite).toBe(expected.colorWrites);
    expect(material.greenWrite).toBe(expected.colorWrites);
    expect(material.blueWrite).toBe(expected.colorWrites);
    expect(material.alphaWrite).toBe(expected.colorWrites);
}

describe('ElementComponentSystem#getImageElementMaterial', () => {
    let device;
    let system;

    beforeEach(() => {
        device = new NullGraphicsDevice();
        system = new ElementComponentSystem({ graphicsDevice: device });
    });

    afterEach(() => {
        system.destroy();
        device.destroy();
    });

    it('starts with no cached materials', () => {
        expect(system.defaultImageMaterials).toEqual([]);
        expect(system.defaultImageMaterial).toBeNull();
        expect(system.defaultImage9SlicedMaterial).toBeNull();
        expect(system.defaultImage9TiledMaterial).toBeNull();
        expect(system.defaultImageMaskMaterial).toBeNull();
        expect(system.defaultImage9SlicedMaskMaterial).toBeNull();
        expect(system.defaultImage9TiledMaskMaterial).toBeNull();
        expect(system.defaultScreenSpaceImageMaterial).toBeNull();
        expect(system.defaultScreenSpaceImage9SlicedMaterial).toBeNull();
        expect(system.defaultScreenSpaceImage9TiledMaterial).toBeNull();
        expect(system.defaultScreenSpaceImageMaskMaterial).toBeNull();
        expect(system.defaultScreenSpaceImageMask9SlicedMaterial).toBeNull();
        expect(system.defaultScreenSpaceImageMask9TiledMaterial).toBeNull();
    });

    it('defaults to the plain image material when called without arguments', () => {
        const material = system.getImageElementMaterial();

        expectBranchState(material, CASES[0]);
        expect(material).toBe(system.defaultImageMaterial);
    });

    if (typeof describe.each === 'function') {
        // no-op guard, kept for readability of the generated tests below
    }

    CASES.forEach((expected) => {
        describe(`${expected.name} (screenSpace=${expected.args[0]}, mask=${expected.args[1]}, nineSliced=${expected.args[2]}, nineSliceTiled=${expected.args[3]})`, () => {
            it('creates the material with the properties of its branch', () => {
                const material = system.getImageElementMaterial(...expected.args);

                expectBaseImageMaterial(material, system);
                expectBranchState(material, expected);
            });

            it('caches the material on the expected system property and in defaultImageMaterials', () => {
                const material = system.getImageElementMaterial(...expected.args);

                expect(system[expected.property]).toBe(material);
                expect(system.defaultImageMaterials).toHaveLength(1);
                expect(system.defaultImageMaterials[0]).toBe(material);
            });

            it('returns the cached material on later calls without creating a new one', () => {
                const first = system.getImageElementMaterial(...expected.args);
                const second = system.getImageElementMaterial(...expected.args);
                const third = system.getImageElementMaterial(...expected.args);

                expect(second).toBe(first);
                expect(third).toBe(first);
                expect(system.defaultImageMaterials).toEqual([first]);
            });
        });
    });

    it('creates one distinct material per flag combination', () => {
        const created = CASES.map(expected => system.getImageElementMaterial(...expected.args));

        // one material per branch
        expect(system.defaultImageMaterials).toHaveLength(CASES.length);
        expect(system.defaultImageMaterials).toEqual(created);

        // every combination owns a separate material that is not shared with any other one
        expect(new Set(created).size).toBe(CASES.length);

        // the materials are stored on the matching named system properties
        CASES.forEach((expected, index) => {
            expect(system[expected.property]).toBe(created[index]);
        });

        // repeated lookups keep returning the very same per-combination instances
        CASES.forEach((expected, index) => {
            expect(system.getImageElementMaterial(...expected.args)).toBe(created[index]);
        });
        expect(system.defaultImageMaterials).toHaveLength(CASES.length);
    });

    it('keeps the mask variants independent from the non-mask variants', () => {
        const unmasked = system.getImageElementMaterial(false, false, false, false);
        const masked = system.getImageElementMaterial(false, true, false, false);

        expect(masked).not.toBe(unmasked);
        expect(masked.redWrite).toBe(false);
        expect(unmasked.redWrite).toBe(true);
        expect(masked.alphaTest).toBe(1);
        expect(unmasked.alphaTest).toBe(0);
        expect(system.defaultImageMaterials).toEqual([unmasked, masked]);
    });

    it('throws if the tiled screen-space mask material is requested before the tiled screen-space material exists', () => {
        // the masked tiled variant is created by cloning the non-masked tiled variant, which does
        // not exist yet on a fresh system
        expect(() => system.getImageElementMaterial(true, true, false, true)).toThrow(TypeError);
        expect(system.defaultScreenSpaceImageMask9TiledMaterial).toBeNull();
        expect(system.defaultScreenSpaceImage9TiledMaterial).toBeNull();
        expect(system.defaultImageMaterials).toEqual([]);
    });

    it('clones the tiled screen-space material for the tiled screen-space mask material', () => {
        const base = system.getImageElementMaterial(true, false, false, true);
        const masked = system.getImageElementMaterial(true, true, false, true);

        // a clone, not the shared instance
        expect(masked).not.toBe(base);
        expect(masked).toBeInstanceOf(StandardMaterial);

        // the clone is reconfigured to be a masked tiled material
        expect(masked).toBe(system.defaultScreenSpaceImageMask9TiledMaterial);
        expect(masked.name).toBe('defaultScreenSpaceImageMask9TiledMaterial');
        expect(masked.nineSlicedMode).toBe(SPRITE_RENDERMODE_TILED);
        expect(masked.depthTest).toBe(false);
        expect(masked.alphaTest).toBe(1);
        expect(masked.redWrite).toBe(false);
        expect(masked.greenWrite).toBe(false);
        expect(masked.blueWrite).toBe(false);
        expect(masked.alphaWrite).toBe(false);

        // the source material keeps its own configuration
        expect(base).toBe(system.defaultScreenSpaceImage9TiledMaterial);
        expect(base.name).toBe('defaultScreenSpaceImage9TiledMaterial');
        expect(base.nineSlicedMode).toBe(SPRITE_RENDERMODE_TILED);
        expect(base.alphaTest).toBe(0);
        expect(base.redWrite).toBe(true);
        expect(base.greenWrite).toBe(true);
        expect(base.blueWrite).toBe(true);
        expect(base.alphaWrite).toBe(true);

        // both materials are tracked, in creation order, and the clone is cached
        expect(system.defaultImageMaterials).toEqual([base, masked]);
        expect(system.getImageElementMaterial(true, true, false, true)).toBe(masked);
        expect(system.defaultImageMaterials).toHaveLength(2);
    });

    it('clones the tiled screen-space material only once', () => {
        system.getImageElementMaterial(true, false, false, true);
        const first = system.getImageElementMaterial(true, true, false, true);
        const second = system.getImageElementMaterial(true, true, false, true);

        expect(second).toBe(first);
        expect(system.defaultImageMaterials).toHaveLength(2);
    });

    describe('nineSliced takes precedence over nineSliceTiled', () => {
        const PRECEDENCE_CASES = [
            {
                args: [true, true],
                property: 'defaultScreenSpaceImageMask9SlicedMaterial',
                name: 'defaultScreenSpaceImageMask9SlicedMaterial',
                notCreated: 'defaultScreenSpaceImageMask9TiledMaterial'
            },
            {
                args: [true, false],
                property: 'defaultScreenSpaceImage9SlicedMaterial',
                name: 'defaultScreenSpaceImage9SlicedMaterial',
                notCreated: 'defaultScreenSpaceImage9TiledMaterial'
            },
            {
                args: [false, true],
                property: 'defaultImage9SlicedMaskMaterial',
                name: 'defaultImage9SlicedMaskMaterial',
                notCreated: 'defaultImage9TiledMaskMaterial'
            },
            {
                args: [false, false],
                property: 'defaultImage9SlicedMaterial',
                name: 'defaultImage9SlicedMaterial',
                notCreated: 'defaultImage9TiledMaterial'
            }
        ];

        PRECEDENCE_CASES.forEach(({ args, property, name, notCreated }) => {
            it(`returns ${name} when both flags are set (screenSpace=${args[0]}, mask=${args[1]})`, () => {
                const material = system.getImageElementMaterial(args[0], args[1], true, true);

                expect(material).toBe(system[property]);
                expect(material.name).toBe(name);
                expect(material.nineSlicedMode).toBe(SPRITE_RENDERMODE_SLICED);
                expect(system[notCreated]).toBeNull();
                expect(system.defaultImageMaterials).toEqual([material]);
            });
        });
    });

    it('returns the tiled variants when only nineSliceTiled is set', () => {
        const tiledMask = system.getImageElementMaterial(false, true, false, true);
        expect(tiledMask.nineSlicedMode).toBe(SPRITE_RENDERMODE_TILED);
        expect(tiledMask.name).toBe('defaultImage9TiledMaskMaterial');
        expect(system.defaultImage9SlicedMaskMaterial).toBeNull();

        const tiledImage = system.getImageElementMaterial(false, false, false, true);
        expect(tiledImage.nineSlicedMode).toBe(SPRITE_RENDERMODE_TILED);
        expect(tiledImage.name).toBe('defaultImage9TiledMaterial');
        expect(system.defaultImage9SlicedMaterial).toBeNull();
    });

    it('treats the flags as booleans, so any truthy value selects the same branch', () => {
        const fromBooleans = system.getImageElementMaterial(true, false, true, false);
        const fromTruthy = system.getImageElementMaterial(1, 0, 'yes', '');

        expect(fromTruthy).toBe(fromBooleans);
        expect(system.defaultImageMaterials).toHaveLength(1);
    });
});
