import { jest } from '@jest/globals';

const mockModulePath = '../../../../../src/scene/particle-system/particle-emitter.js';

jest.unstable_mockModule(mockModulePath, () => {
    const ParticleEmitter = jest.fn(function (graphicsDevice, options) {
        this.graphicsDevice = graphicsDevice;
        this.options = options;
        this.meshInstance = {
            node: null,
            visible: true
        };
        this.colorMap = options.colorMap;
        this.drawOrder = 0;
    });

    return { ParticleEmitter };
});

const { ParticleSystemComponent } = await import('../../../../../src/framework/components/particle-system/component.js');
const { Asset } = await import('../../../../../src/framework/asset/asset.js');
const { ParticleEmitter } = await import(mockModulePath);

function createEventHandle() {
    return { off: jest.fn() };
}

function createHarness({ autoPlay = true, depthSoftening = 0, emitter = null } = {}) {
    const layerEvents = {
        add: jest.fn(() => createEventHandle()),
        remove: jest.fn(() => createEventHandle())
    };
    const layers = {
        on: jest.fn((event, callback, context) => {
            if (event === 'add') return layerEvents.add(event, callback, context);
            if (event === 'remove') return layerEvents.remove(event, callback, context);
            return createEventHandle();
        }),
        getLayerById: jest.fn()
    };
    const sceneEvents = {
        on: jest.fn(() => createEventHandle())
    };
    const scene = {
        layers,
        on: sceneEvents.on
    };
    const assets = {
        get: jest.fn(),
        load: jest.fn()
    };
    const graphicsDevice = {
        disableParticleSystem: false
    };
    const system = {
        app: {
            scene,
            assets,
            graphicsDevice
        }
    };
    const entity = {
        enabled: true
    };
    const component = new ParticleSystemComponent(system, entity);

    component._autoPlay = autoPlay;
    component._depthSoftening = depthSoftening;
    component.emitter = emitter;
    component.addMeshInstanceToLayers = jest.fn();
    component.pause = jest.fn();
    component._requestDepth = jest.fn();

    return {
        assets,
        component,
        entity,
        graphicsDevice,
        layerEvents,
        layers,
        scene,
        sceneEvents,
        system
    };
}

describe('ParticleSystemComponent#onEnable', () => {
    beforeEach(() => {
        ParticleEmitter.mockClear();
    });

    it('loads every unloaded Asset instance referenced by an asset property', () => {
        const { assets, component } = createHarness();
        const colorAsset = new Asset('color', 'texture');
        const normalAsset = new Asset('normal', 'texture');
        const meshAsset = new Asset('mesh', 'model');
        const renderAsset = new Asset('render', 'render');

        component._colorMapAsset = colorAsset;
        component._normalMapAsset = normalAsset;
        component._meshAsset = meshAsset;
        component._renderAsset = renderAsset;

        component.onEnable();

        expect(assets.load.mock.calls).toEqual([
            [colorAsset],
            [normalAsset],
            [meshAsset],
            [renderAsset]
        ]);
        expect(assets.get).not.toHaveBeenCalled();
    });

    it('resolves positive asset ids through the asset registry before loading them', () => {
        const { assets, component } = createHarness();
        const resolvedAsset = new Asset('resolved', 'texture');

        assets.get.mockReturnValue(resolvedAsset);
        component._colorMapAsset = '7';

        component.onEnable();

        expect(assets.get).toHaveBeenCalledWith('7');
        expect(assets.load).toHaveBeenCalledWith(resolvedAsset);
    });

    it('skips negative asset ids without querying or loading the asset registry', () => {
        const { assets, component } = createHarness();

        component._colorMapAsset = '-4';
        component._normalMapAsset = -1;
        component._meshAsset = 'not-an-id';

        component.onEnable();

        expect(assets.get).not.toHaveBeenCalled();
        expect(assets.load).not.toHaveBeenCalled();
    });

    it('treats zero as a valid asset id', () => {
        const { assets, component } = createHarness();
        const zeroAsset = new Asset('zero', 'texture');

        assets.get.mockReturnValue(zeroAsset);
        component._renderAsset = '0';

        component.onEnable();

        expect(assets.get).toHaveBeenCalledWith('0');
        expect(assets.load).toHaveBeenCalledWith(zeroAsset);
    });

    it('does not reload assets which already have a resource', () => {
        const { assets, component } = createHarness();
        const loadedAsset = new Asset('loaded', 'texture');
