describe('WebglRenderTarget#init', () => {
    let consoleWarnSpy;
    let consoleErrorSpy;

    beforeEach(() => {
        consoleWarnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});
        consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    });

    afterEach(() => {
        consoleWarnSpy.mockRestore();
        consoleErrorSpy.mockRestore();
    });

    describe('initialization state', () => {
        it('reports not initialized before init and initialized afterwards', () => {
            const device = createMockDevice();
            const rt = new WebglRenderTarget();

            expect(rt.initialized).toBe(false);

            rt.init(device, createMockTarget());

            expect(rt.initialized).toBe(true);
            expect(consoleErrorSpy).not.toHaveBeenCalled();
        });

        it('logs an assertion when initialized twice but keeps the render target usable', () => {
            const device = createMockDevice();

            const rt1 = new WebglRenderTarget();
            rt1.init(device, createMockTarget({ _samples: 2, _depth: true, _depthBuffer: depthBuffer }));

            const rt2 = new WebglRenderTarget();
            rt2.init(device, createMockTarget({ _samples: 4, _depth: true, _depthBuffer: depthBuffer }));

            expect(rt2._glMsaaDepthBuffer).not.toBe(rt1._glMsaaDepthBuffer);
            expect(rt2.msaaDepthBufferKey).not.toBe(rt1.msaaDepthBufferKey);
            expect(gl.createRenderbuffer).toHaveBeenCalledTimes(2);
        });

        it('creates per-color-buffer resolve framebuffers when MSAA and MRT are combined', () => {
            const gl = createMockGl();
            const device = createMockDevice(gl);
            const buffer0 = createMockColorBuffer({ impl: { _glTexture: { id: 0 }, _glInternalFormat: GL.RGBA8 } });
            const buffer1 = createMockColorBuffer({ impl: { _glTexture: { id: 1 }, _glInternalFormat: GL.RGBA8 } });

            const rt = new WebglRenderTarget();
            rt.init(device, createMockTarget({ _colorBuffers: [buffer0, buffer1], _samples: 4 }));

            expect(rt.colorMrtFramebuffers).toHaveLength(2);
            const [pair0, pair1] = rt.colorMrtFramebuffers;
            expect(pair0.msaaFB).toBeTruthy();
            expect(pair0.resolveFB).toBeTruthy();
            expect(pair0.msaaFB).not.toBe(pair0.resolveFB);
            expect(pair0.msaaFB).not.toBe(pair1.msaaFB);

            // the two resolve framebuffers hold the two color textures
            expect(gl.framebufferTexture2D).toHaveBeenCalledWith(
                gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, buffer0.impl._glTexture, 0
            );
            expect(gl.framebufferTexture2D).toHaveBeenCalledWith(
                gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, buffer1.impl._glTexture, 0
            );

            // rendering is restored to the main multisampled framebuffer at the end
            expect(device.setFramebuffer).toHaveBeenLastCalledWith(rt._glFrameBuffer);
            expect(gl.drawBuffers).toHaveBeenLastCalledWith([gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT0 + 1]);
            expect(consoleErrorSpy).not.toHaveBeenCalled();
        });

        it('does not create MRT framebuffers for a single color buffer', () => {
            const gl = createMockGl();
            const device = createMockDevice(gl);
            const colorBuffer = createMockColorBuffer({ impl: { _glTexture: { id: 0 }, _glInternalFormat: GL.RGBA8 } });

            const rt = new WebglRenderTarget();
            rt.init(device, createMockTarget({ _colorBuffers: [colorBuffer], _samples: 4 }));

            // the single sampled resolve framebuffer holds the only color attachment
            expect(rt.colorMrtFramebuffers).toBeNull();
            expect(gl.drawBuffers).toHaveBeenCalledTimes(1);
            expect(gl.drawBuffers).toHaveBeenCalledWith([gl.COLOR_ATTACHMENT0]);
            expect(gl.framebufferTexture2D).toHaveBeenCalledTimes(1);
        });
    });

    describe('validation', () => {
        it('warns once about an invalid render target size', () => {
            const device = createMockDevice();
            const target = createMockTarget({ width: 0, height: 0 });

            const rt = new WebglRenderTarget();
            rt.init(device, target);

            expect(consoleWarnSpy).toHaveBeenCalledWith('Invalid render target size: 0 x 0', target);
        });

        it('warns about negative render target dimensions', () => {
            const device = createMockDevice();
            const target = createMockTarget({ width: -3, height: -7 });
            const rt = new WebglRenderTarget();

            rt.init(device, target);

            expect(consoleWarnSpy).toHaveBeenCalledTimes(1);
            expect(consoleWarnSpy).toHaveBeenCalledWith('Invalid render target size: -3 x -7', target);
        });

        it('warns only once for the same invalid render target size', () => {
            const device = createMockDevice();
            const target = createMockTarget({ width: 1, height: 0 });

            new WebglRenderTarget().init(device, target);
            new WebglRenderTarget().init(device, createMockTarget({ width: 1, height: 0 }));

            expect(consoleWarnSpy).toHaveBeenCalledTimes(1);
            expect(consoleWarnSpy).toHaveBeenCalledWith('Invalid render target size: 1 x 0', expect.anything());
        });

        it('logs an assertion when the framebuffer is incomplete', () => {
            const gl = createMockGl({
                checkFramebufferStatus: jest.fn(() => GL.FRAMEBUFFER_INCOMPLETE_ATTACHMENT)
            });
            const device = createMockDevice(gl);
            const target = createMockTarget({ name: 'broken-target' });

            const rt = new WebglRenderTarget();
            rt.init(device, target);

            expect(gl.checkFramebufferStatus).toHaveBeenCalledWith(gl.FRAMEBUFFER);
            expect(consoleErrorSpy).toHaveBeenCalledWith(
                'ASSERT FAILED: ',
                expect.stringContaining('FRAMEBUFFER_INCOMPLETE_ATTACHMENT'),
                target
            );
            expect(consoleErrorSpy.mock.calls[0][1]).toContain('broken-target');
        });

        it('logs an assertion for an unsupported framebuffer configuration', () => {
            const gl = createMockGl({
                checkFramebufferStatus: jest.fn(() => GL.FRAMEBUFFER_UNSUPPORTED)
            });
            const device = createMockDevice(gl);
            const target = createMockTarget({ name: 'unsupported-target' });

            const rt = new WebglRenderTarget();
            rt.init(device, target);

            expect(consoleErrorSpy).toHaveBeenCalledWith(
                'ASSERT FAILED: ',
                expect.stringContaining('FRAMEBUFFER_UNSUPPORTED'),
                target
            );
        });

        it('validates each distinct framebuffer configuration only once per device', () => {
            const gl = createMockGl();
            const device = createMockDevice(gl);

            new WebglRenderTarget().init(device, createMockTarget());
            expect(gl.checkFramebufferStatus).toHaveBeenCalledTimes(1);

            // same configuration (formats, depth, samples) - already validated
            new WebglRenderTarget().init(device, createMockTarget({ width: 512, height: 512 }));
            expect(gl.checkFramebufferStatus).toHaveBeenCalledTimes(1);

            // different configuration (depth enabled) - validated again
            new WebglRenderTarget().init(device, createMockTarget({ _depth: true }));
            expect(gl.checkFramebufferStatus).toHaveBeenCalledTimes(2);
        });

        it('does not log an assertion for a complete framebuffer', () => {
            const gl = createMockGl();
            const device = createMockDevice(gl);
            const rt = new WebglRenderTarget();

            rt.init(device, createMockTarget());

            expect(gl.checkFramebufferStatus).toHaveBeenCalled();
            expect(consoleErrorSpy).not.toHaveBeenCalled();
        });
    });
});

