import { describe, it, expect, jest, afterEach } from '@jest/globals';

import { Color } from '../../../../src/core/math/color.js';
import { Vec3 } from '../../../../src/core/math/vec3.js';
import { Debug } from '../../../../src/core/debug.js';
import {
    LIGHTTYPE_DIRECTIONAL,
    LIGHTTYPE_SPOT,
    MASK_BAKE,
    SHADERDEF_LM
} from '../../../../src/scene/constants.js';
import { MeshInstance } from '../../../../src/scene/mesh-instance.js';
import { Lightmapper } from '../../../../src/framework/lightmapper/lightmapper.js';
import { BakeLightAmbient } from '../../../../src/framework/lightmapper/bake-light-ambient.js';

const PASS_DIR = 1;

/**
 * Creates a fake render target with the shape the RenderPass base class needs during init().
 */
function createRenderTarget(size) {
    const colorBuffer = { width: size, height: size };
    return {
        colorBuffer,
        samples: 1,
        _colorBuffers: [colorBuffer],
        depthBuffer: null
    };
}

/**
 * Creates a fake mesh instance that records every material assignment made to it.
 */
function createMeshInstance(initialMaterial = null) {
    let current = initialMaterial;
    const materialHistory = [];

    const meshInstance = {
        mask: 0,
        _shaderDefs: 0,
        setLightmapped: jest.fn(),
        setRealtimeLightmap: jest.fn(),
        materialHistory
    };

    Object.defineProperty(meshInstance, 'material', {
        configurable: true,
        enumerable: true,
        get() {
            return current;
        },
        set(value) {
            current = value;
            materialHistory.push(value);
        }
    });

    return meshInstance;
}

function createBakeNode(size, instanceCount, passCount) {
    return {
        meshInstances: Array.from({ length: instanceCount }, () => createMeshInstance()),
        renderTargets: Array.from({ length: passCount }, () => createRenderTarget(size))
    };
}

function createBakeLight(options = {}) {
    const light = {
        type: LIGHTTYPE_DIRECTIONAL,
        _node: { name: 'TestLight' },
        enabled: true,
        bakeDir: false,
        visibleThisFrame: false,
        ...options.light
    };

    return {
        light,
        numVirtualLights: options.numVirtualLights ?? 1,
        lightBounds: { intersects: jest.fn(() => true) },
        startBake: jest.fn(),
        endBake: jest.fn(),
        prepareVirtualLight: jest.fn(),
        restore: jest.fn(),
        ...options.bakeLight
    };
}

function createAmbientBakeLight(options = {}) {
    // An actual BakeLightAmbient instance is expensive to construct (it builds an Entity), but
    // bakeInternal only relies on the prototype for its `instanceof` check, so create the object
    // with the right prototype and supply the members that are read directly.
    const bakeLight = Object.create(BakeLightAmbient.prototype);

    bakeLight.light = {
        type: LIGHTTYPE_DIRECTIONAL,
        _node: { name: 'AmbientLight' },
        enabled: true,
        bakeDir: false,
        ...options.light
    };

    Object.defineProperty(bakeLight, 'numVirtualLights', {
        configurable: true,
        writable: true,
        value: options.numVirtualLights ?? 1
    });

    bakeLight.lightBounds = { intersects: jest.fn(() => true) };
    bakeLight.startBake = jest.fn();
    bakeLight.endBake = jest.fn();
    bakeLight.prepareVirtualLight = jest.fn();
    bakeLight.restore = jest.fn();

    return bakeLight;
}

/**
 * Builds a Lightmapper whose leaf operations are stubbed. This isolates bakeInternal's
 * orchestration/looping logic, which is what the tests target.
 */
function createHarness(options = {}) {
    const passCount = options.passCount ?? 1;
    const nodeSizes = options.nodeSizes ?? [32];
    const instancesPerNode = options.instancesPerNode ?? 1;

    const bakeNodes = nodeSizes.map(size => createBakeNode(size, instancesPerNode, passCount));
    const allNodes = options.allNodes ?? [{ restore: jest.fn() }];

    const device = {
        scope: { resolve: jest.fn(() => ({ setValue: jest.fn() })) },
        pushMarker: jest.fn(),
        popMarker: jest.fn(),
        renderPassIndex: 0
    };

    const scene = {
        layers: { _update: jest.fn() },
        clusteredLightingEnabled: options.clustered ?? false,
        updateShaders: options.updateShaders ?? false,
        ambientLight: new Color(0.25, 0.5, 0.75, 1),
        ambientBake: false,
        lighting: {}
    };

    const renderer = {
        shadowMapCache: { clear: jest.fn() },
        collectLights: jest.fn(),
        updateCpuSkinMatrices: jest.fn(),
        gpuUpdate: jest.fn(),
        updateShaders: jest.fn(),
        renderForwardLayer: jest.fn(),
        lightTextureAtlas: { update: jest.fn() },
        lights: []
    };

    const lm = new Lightmapper(device, {}, scene, renderer, {});

    // State normally created by initBake(), stubbed out here.
    lm.blackTex = { name: 'lightmapBlack' };
    lm.camera = { clearColor: new Color(0, 0, 0, 1) };
    lm.passMaterials = [{ pass: 0 }, { pass: 1 }];
    lm.ambientAOMaterial = { ambientAO: true };
    lm.constantBakeDir = { setValue: jest.fn() };
    lm.lightingParams = { lightingParams: true };
    lm.worldClusters = { update: jest.fn() };
    lm.materials = [];

    // One spare/temp render target per lightmap size, as allocateTextures would have made.
    for (const size of new Set(nodeSizes)) {
        lm.renderTargets.set(size, createRenderTarget(size));
    }

    const allLights = options.allLights ?? [];
    const bakeLights = options.bakeLights ?? [];
    const casters = options.casters ?? [{ aabb: {} }];
    const casterBounds = options.casterBounds ?? {
        center: new Vec3(0, 0, 0),
        halfExtents: new Vec3(1, 1, 1)
    };
    const shadowCam = options.shadowCam ?? { fakeShadowCamera: true };

    lm.createMaterials = jest.fn();
    lm.setupScene = jest.fn();
    lm.computeNodesBounds = jest.fn();
    lm.allocateTextures = jest.fn();
    lm.prepareLightsToBake = jest.fn((outAllLights, outBakeLights) => {
        outAllLights.push(...allLights);
        outBakeLights.push(...bakeLights);
    });
    lm.updateTransforms = jest.fn();
    lm.prepareShadowCasters = jest.fn(() => casters);
    lm.computeBounds = jest.fn(() => casterBounds);
    lm.lightCameraPrepare = jest.fn(() => shadowCam);
    lm.lightCameraPrepareAndCull = options.cull ?? jest.fn(() => true);
    lm.renderShadowMap = options.renderShadowMap ?? jest.fn(() => true);
    lm.postprocessTextures = jest.fn();

    return {
        lm,
        device,
        scene,
        renderer,
        bakeNodes,
        allNodes,
        allLights,
        bakeLights,
        casters,
        casterBounds,
        shadowCam,
        passCount
    };
}

