import { WebglTexture } from '../../../../../src/platform/graphics/webgl/webgl-texture.js';

const GL = {
    TEXTURE_2D: 0x0DE1,
    TEXTURE_CUBE_MAP: 0x8513,
    TEXTURE_3D: 0x806F,
    TEXTURE_2D_ARRAY: 0x8C1A,
    TEXTURE_CUBE_MAP_POSITIVE_X: 0x8515
};

const GL_METHODS = [
    'texStorage3D', 'generateMipmap',
    'texImage2D', 'texSubImage2D', 'compressedTexImage2D', 'compressedTexSubImage2D',
    'texImage3D', 'compressedTexImage3D', 'texSubImage3D', 'compressedTexSubImage3D',
    'texElementImage2D'
];

function createGl() {
    const gl = { ...GL };
    GL_METHODS.forEach((name) => {
        gl[name] = jest.fn();
    });
    return gl;
}

function createDevice(overrides = {}) {
    return {
        gl: createGl(),
        _vram: { tex: 0 },
        maxTextureSize: 4096,
        maxCubeMapSize: 4096,
        supportsHtmlTextures: false,
        setUnpackFlipY: jest.fn(),
        setUnpackPremultiplyAlpha: jest.fn(),
        setUnpackAlignment: jest.fn(),
        _isBrowserInterface: jest.fn(() => false),
        _isImageBrowserInterface: jest.fn(() => false),
        _isHTMLElementInterface: jest.fn(() => false),
        _isImageVideoInterface: jest.fn(() => false),
        ...overrides
    };
}

function createTexture(device, overrides = {}) {
    return {
        device,
        _needsUpload: true,
        _needsMipmapsUpload: false,
        _mipmapsUploaded: false,
        numLevels: 1,
        _levels: [null],
        _levelsUpdated: [true],
        _cubemap: false,
        _volume: false,
        array: false,
        _arrayLength: 0,
        _compressed: false,
        _integerFormat: false,
        _premultiplyAlpha: false,
        _flipY: false,
        _width: 4,
        _height: 4,
        _depth: 1,
        _mipmaps: false,
        _gpuSize: 0,
        gpuSize: 16,
        releaseSourceAfterUpload: false,
        adjustVramSizeTracking: jest.fn(),
        releaseImageSources: jest.fn(),
        ...overrides
    };
}

function createImpl(texture, overrides = {}) {
    const impl = new WebglTexture(texture);
    impl._glTarget = 'TARGET';
    impl._glFormat = 'FORMAT';
    impl._glInternalFormat = 'INTERNAL_FORMAT';
    impl._glPixelType = 'PIXEL_TYPE';
    impl._glCreated = false;
    return Object.assign(impl, overrides);
}

function makeSetup(deviceOverrides, textureOverrides, implOverrides) {
    const device = createDevice(deviceOverrides);
    const texture = createTexture(device, textureOverrides);
    const impl = createImpl(texture, implOverrides);
    return { device, texture, impl };
}

