        it('downsamples oversized images before uploading', () => {
            const originalDocument = global.document;
            const drawImage = jest.fn();
            const canvas = {
                width: 0,
                height: 0,
                getContext: jest.fn(() => ({ drawImage }))
            };
            global.document = {
                createElement: jest.fn(() => canvas)
            };
            const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});
            const image = { width: 8192, height: 4096 };

            const { device, texture, impl } = makeSetup({
                maxTextureSize: 4096,
                _isBrowserInterface: jest.fn((value) => value === image),
                _isImageBrowserInterface: jest.fn((value) => value === image)
            }, {
                _levels: [image]
            });

            try {
                impl.upload(device, texture);

                expect(global.document.createElement).toHaveBeenCalledWith('canvas');
                expect(canvas.width).toBe(4096);
                expect(canvas.height).toBe(2048);
                expect(drawImage).toHaveBeenCalledWith(image, 0, 0, 8192, 4096, 0, 0, 4096, 2048);
                expect(device.gl.texImage2D).toHaveBeenCalledWith(
                    GL.TEXTURE_2D, 0, 'INTERNAL_FORMAT', 'FORMAT', 'PIXEL_TYPE', canvas
                );
                expect(texture._width).toBe(4096);
                expect(texture._height).toBe(2048);
            } finally {
                global.document = originalDocument;
                warnSpy.mockRestore();
            }
        });
    });

