            batchedMeshInstance.stencilFront = sourceMeshInstance.stencilFront;
            batchedMeshInstance.stencilBack = sourceMeshInstance.stencilBack;
            batchedMeshInstance.flipFacesFactor = getScaleSign(sourceMeshInstance);

