import { PRIMITIVE_TRIFAN, PRIMITIVE_TRISTRIP, PRIMITIVE_TRIANGLES, INDEXFORMAT_UINT16, INDEXFORMAT_UINT32 } from './src/platform/graphics/constants.js';

