  const m = batch.meshInstance.mesh;
  console.log(type, 'indexed', m.primitive[0].indexed, 'type', m.primitive[0].type, 'count', m.primitive[0].count, 'idx', Array.from(new Uint16Array(m.indexBuffer[0].storage)));
}
// non indexed triangles
{
  const m0 = new Mesh(device);
  m0.setPositions(new Float32Array([0,0,0, 1,0,0, 1,1,0]));
  m0.update(PRIMITIVE_TRIANGLES, false);
  const mi = new MeshInstance(m0, mat, new GraphNode('n'));
  mi._updateAabb=false; mi.aabb=new BoundingBox();
  const batch = bm.create([mi], false, 0);
  const m = batch.meshInstance.mesh;
  console.log('nonidx tri:', !!batch, m.primitive[0].indexed, m.primitive[0].type, m.primitive[0].count, m.vertexBuffer.numVertices);
}
// large
{
  const n = 0x10001;
  const positions = new Float32Array(n*3);
  const m0 = new Mesh(device);
  m0.setPositions(positions);
  m0.setIndices(new Uint16Array([0,1,2]));
  m0.update();
  const mi = new MeshInstance(m0, mat, new GraphNode('n'));
  mi._updateAabb=false; mi.aabb=new BoundingBox();
  const batch = bm.create([mi], false, 0);
  const m = batch.meshInstance.mesh;
  console.log('large vb', m.vertexBuffer.numVertices, 'fmt', m.indexBuffer[0].getFormat(), INDEXFORMAT_UINT16, INDEXFORMAT_UINT32);
}
EOF"}

