const CAMERA_POSITION = new Vec3(1.5, -2.5, 3.5);

/**
 * Identity projection with distinct x/y scales, so the per-axis pixel focal lengths are easy to
 * state as expectations (focal = width * 2, focalY = height * 4).
 *
 * @returns {Mat4} The projection matrix.
 */
const createProjectionMatrix = () => {
    const matrix = new Mat4();
    matrix.data[0] = 2;
    matrix.data[5] = 4;
    return matrix;
};

/**
 * Creates a fake XR views array (two eyes) with distinguishable per-eye matrices.
 *
 * @returns {Array<object>} The two XR views.
 */
const createXrViews = () => {
    const eye = (offset) => ({
        projViewOffMat: { data: new Float32Array(16).map((value, index) => offset + index) },
        viewOffMat: { data: new Float32Array(16).map((value, index) => offset + 100 + index) },
        projMat: { data: new Float32Array(16).map((value, index) => offset + 200 + index) }
    });

    const views = [eye(0), eye(1000)];

    // eye-0 projection scales drive the shared focal length uniforms
    for (const view of views) {
        view.projMat.data[0] = 2;
        view.projMat.data[5] = 4;
    }

    return views;
};

/**
 * Creates a camera node double providing what dispatch reads from it.
 *
 * @param {object} [options] - Camera configuration overrides.
 * @returns {object} The camera node double.
 */
const createCameraNode = ({
    position = CAMERA_POSITION,
    worldTransform = new Mat4().setScale(1, 1, 5),
    viewMatrix = new Mat4(),
    projectionMatrix = createProjectionMatrix(),
    nearClip = 0.25,
    farClip = 750,
    projection = PROJECTION_PERSPECTIVE,
    xrViews = null
} = {}) => {
    const cam = {
        viewMatrix,
        projectionMatrix,
        nearClip,
        farClip,
        projection,
        xrViews,
        updateViewTransforms: jest.fn()
    };

    return {
        camera: { camera: cam },
        getPosition: jest.fn(() => position),
        getWorldTransform: jest.fn(() => worldTransform)
    };
};

/**
 * Creates a work-buffer double exposing a subset of resource streams as textures.
 *
 * @returns {object} The work buffer double.
 */
const createWorkBuffer = () => {
    const textures = {
        dataColor: { id: 'dataColorTexture' },
        dataCenter: { id: 'dataCenterTexture' }
    };

    return {
        format: {
            resourceStreams: [
                { name: 'dataColor' },
                { name: 'dataCenter' },
                { name: 'dataEmptyStream' }
            ]
        },
        getTexture: jest.fn(name => textures[name]),
        textureSize: 2048
    };
};

/**
 * Creates a projector instance backed by mocked collaborators (no GPU required).
 *
 * @param {object} [options] - Options.
 * @param {Array<string>} [options.log] - Optional call-order log.
 * @returns {object} The projector double.
 */
const createProjector = ({ log = null } = {}) => {
    const projector = Object.create(GSplatProjector.prototype);

    const compute = {
        setParameter: jest.fn((name) => {
            log?.push(`setParameter:${name}`);
        }),
        setupDispatchThreads: jest.fn((count) => {
            log?.push(`setupDispatchThreads:${count}`);
        })
    };

    projector.device = {
        isWebGPU: false,
        computeDispatch: jest.fn((computes, name) => {
            log?.push(`computeDispatch:${name}`);
        })
    };
    projector.renderCounter = {
        clear: jest.fn(() => {
            log?.push('renderCounter.clear');
        })
    };
    projector.projCache = { id: 'projCache' };
    projector.sortKeys = { id: 'sortKeys' };
    projector.binWeightsUtil = new GSplatSortBinWeights();
    projector.binWeightsBuffer = {
        write: jest.fn((offset, data) => {
            log?.push(`binWeightsBuffer.write:${offset}`);
        })
    };
    projector.cameraPositionData = new Float32Array(3);
    projector.cameraDirectionData = new Float32Array(3);

    projector._updateMaterial = jest.fn((material, userCacheWords) => {
        log?.push('_updateMaterial');
    });
    projector._ensureCapacity = jest.fn((capacity) => {
        log?.push(`_ensureCapacity:${capacity}`);
    });
    projector._getProjectorCompute = jest.fn((...args) => {
        log?.push('_getProjectorCompute');
        return compute;
    });

    projector.compute = compute;

    return projector;
};

/**
 * Builds a complete dispatch() params object.
 *
 * @param {object} [overrides] - Parameter overrides (cameraNode/xrViews are handled specially).
 * @returns {object} The dispatch params.
