            expect(weights[0]).toBe(0);
            for (let i = 0; i < GSplatSortBinWeights.NUM_BINS; i++) {
                expect(weights[i * 2 + 1]).toBeGreaterThanOrEqual(1);
                if (i > 0) {
                    expect(weights[i * 2]).toBe(weights[(i - 1) * 2] + weights[(i - 1) * 2 + 1]);
                }
            }

