const createProjector = ({ log = null } = {}) => {
    const projector = Object.create(GSplatProjector.prototype);

    const compute = {
        setParameter: jest.fn((name) => {
            log?.push(`setParameter:${name}`);
        }),
        setupDispatchThreads: jest.fn((count) => {
            log?.push(`setupDispatchThreads:${count}`);
        })
    };

    projector.device = {
        isWebGPU: false,
        computeDispatch: jest.fn((computes, name) => {
            log?.push(`computeDispatch:${name}`);
        })
    };
    projector.renderCounter = {
        clear: jest.fn(() => {
            log?.push('renderCounter.clear');
        })
    };
    projector.projCache = { id: 'projCache' };
    projector.sortKeys = { id: 'sortKeys' };
    projector.binWeightsUtil = new GSplatSortBinWeights();
    projector.binWeightsBuffer = {
        write: jest.fn((offset, data) => {
            log?.push(`binWeightsBuffer.write:${offset}`);
        })
    };
    projector.cameraPositionData = new Float32Array(3);
    projector.cameraDirectionData = new Float32Array(3);

    projector._updateMaterial = jest.fn((material, userCacheWords) => {
        log?.push('_updateMaterial');
    });
    projector._ensureCapacity = jest.fn((capacity) => {
        log?.push(`_ensureCapacity:${capacity}`);
    });
    projector._getProjectorCompute = jest.fn((...args) => {
        log?.push('_getProjectorCompute');
        return compute;
    });

    projector.compute = compute;

    return projector;
};

/**
 * Builds a complete dispatch() params object.
 *
 * @param {object} [overrides] - Parameter overrides.
 * @param {object[]|null} [overrides.xrViews] - XR views used to build the camera node.
 * @param {object|null} [overrides.cameraNode] - Explicit camera node replacing the default one.
 * @returns {object} The dispatch params.
 */
const createParams = ({ xrViews = null, cameraNode = null, ...overrides } = {}) => {
    return {
        workBuffer: createWorkBuffer(),
        cameraNode: cameraNode ?? createCameraNode({ xrViews }),
        compactedSplatIds: { id: 'compactedSplatIds' },
        sortElementCountBuffer: { id: 'sortElementCount' },
        totalCapacity: 1024,
        radialSort: false,
        numBits: 16,
        minDist: 1,
        maxDist: 101,
        alphaClip: 0.5,
        minPixelSize: 1.5,
        minContribution: 0.01,
        viewportWidth: 800,
        viewportHeight: 600,
        ...overrides
    };
};

/**
 * Returns the value forwarded for a uniform, or undefined when it was never set. The last call
 * wins, mirroring how the projector overrides user material parameters on a name collision.
 *
 * @param {object} compute - The compute double.
 * @param {string} name - The parameter name.
 * @returns {*} The forwarded value.
 */
const paramValue = (compute, name) => {
    const calls = compute.setParameter.mock.calls.filter(([parameterName]) => parameterName === name);
    return calls.length ? calls[calls.length - 1][1] : undefined;
};

/**
 * Returns whether a parameter was ever forwarded.
 *
 * @param {object} compute - The compute double.
 * @param {string} name - The parameter name.
 * @returns {boolean} True when the parameter was set at least once.
 */
const hasParam = (compute, name) => {
    return compute.setParameter.mock.calls.some(([parameterName]) => parameterName === name);
};

describe('GSplatProjector#dispatch', () => {

    describe('resources and camera uniforms', () => {
        let projector;
        let params;
        let compute;

        beforeEach(() => {
            projector = createProjector();
            params = createParams();
            compute = projector.compute;
            projector.dispatch(params);
        });

        it('binds the projector storage buffers and the work-buffer textures', () => {
            expect(paramValue(compute, 'compactedSplatIds')).toBe(params.compactedSplatIds);
            expect(paramValue(compute, 'sortElementCount')).toBe(params.sortElementCountBuffer);
            expect(paramValue(compute, 'projCache')).toBe(projector.projCache);
            expect(paramValue(compute, 'sortKeys')).toBe(projector.sortKeys);
            expect(paramValue(compute, 'renderCounter')).toBe(projector.renderCounter);
            expect(paramValue(compute, 'binWeights')).toBe(projector.binWeightsBuffer);

            // only streams that resolve to a texture are bound
            expect(compute.setParameter).toHaveBeenCalledWith('dataColor', { id: 'dataColorTexture' });
            expect(compute.setParameter).toHaveBeenCalledWith('dataCenter', { id: 'dataCenterTexture' });
            expect(hasParam(compute, 'dataEmptyStream')).toBe(false);
        });

        it('forwards the camera position and the normalized camera direction', () => {
            expect(paramValue(compute, 'cameraPosition')).toBe(projector.cameraPositionData);
            expect(Array.from(projector.cameraPositionData)).toEqual([1.5, -2.5, 3.5]);

            // the world transform has a z scale of 5, so a unit-length z axis proves normalization
            expect(paramValue(compute, 'cameraDirection')).toBe(projector.cameraDirectionData);
            expect(Array.from(projector.cameraDirectionData)).toEqual([0, 0, 1]);
        });

        it('forwards the view matrix and the view-projection matrix', () => {
            const cam = params.cameraNode.camera.camera;

            expect(Array.from(paramValue(compute, 'viewMatrix'))).toEqual(Array.from(cam.viewMatrix.data));

            // identity view * projection with only x/y scaled
            const viewProj = paramValue(compute, 'viewProj');
            expect(viewProj).toHaveLength(16);
            expect(viewProj[0]).toBe(2);
            expect(viewProj[5]).toBe(4);
            expect(viewProj[10]).toBe(1);
            expect(viewProj[15]).toBe(1);
        });

        it('forwards the projection scalars and the clipping ranges', () => {
            const cam = params.cameraNode.camera.camera;

            expect(paramValue(compute, 'focal')).toBe(1600); // 800 * 2
