import { describe, expect, it, jest } from '@jest/globals';

import { Vec3 } from '../../../../src/core/math/vec3.js';
import { NullGraphicsDevice } from '../../../../src/platform/graphics/null/null-graphics-device.js';
import { WorldClustersDebug } from '../../../../src/scene/lighting/world-clusters-debug.js';

const createWorldClusters = ({
    cells = [1, 1, 1],
    boundsMin = [0, 0, 0],
    boundsDelta = [2, 2, 2],
    counts = null,
    maxCellLightCount = 4
} = {}) => {
    const cellCount = new Vec3(cells[0], cells[1], cells[2]);
    const numCells = cells[0] * cells[1] * cells[2];
    return {
        cells: cellCount,
        _cells: cellCount,
        lightsBuffer: {
            boundsMin: new Vec3(boundsMin[0], boundsMin[1], boundsMin[2]),
            boundsDelta: new Vec3(boundsDelta[0], boundsDelta[1], boundsDelta[2])
        },
        counts: counts ?? new Array(numCells).fill(0),
        _maxCellLightCount: maxCellLightCount
    };
};

const createScene = (device) => {
    const layer = { name: 'defaultDrawLayer' };
    return {
        device,
        defaultDrawLayer: layer,
        drawLineArrays: jest.fn()
    };
};

describe('WorldClustersDebug render', () => {
    it('draws the cluster grid lines and resets the grid position buffer', () => {
        const device = new NullGraphicsDevice();
        const scene = createScene(device);
        const debug = new WorldClustersDebug();
        const worldClusters = createWorldClusters();

        debug.render(worldClusters, scene);

        expect(scene.drawLineArrays).toHaveBeenCalledTimes(1);
        const [positions, colors] = scene.drawLineArrays.mock.calls[0];

        expect(positions).toEqual([
            0, 0, 0, 0, 2, 0,
            0, 0, 2, 0, 2, 2,
            2, 0, 0, 2, 2, 0,
            2, 0, 2, 2, 2, 2,

            0, 0, 0, 0, 0, 2,
            0, 2, 0, 0, 2, 2,
            2, 0, 0, 2, 0, 2,
            2, 2, 0, 2, 2, 2,

            0, 0, 0, 2, 0, 0,
            0, 0, 2, 2, 0, 2,
            0, 2, 0, 2, 2, 0,
            0, 2, 2, 2, 2, 2
        ]);
        expect(colors).toHaveLength(24 * 4);
        for (let i = 0; i < colors.length; i += 4) {
            expect(colors[i]).toBeCloseTo(0.3);
            expect(colors[i + 1]).toBeCloseTo(0.3);
            expect(colors[i + 2]).toBeCloseTo(0.3);
            expect(colors[i + 3]).toBeCloseTo(1);
        }

        // the position buffer is emptied after each render, and reused
        expect(debug.gridPositions).toBe(positions);
        expect(debug.gridPositions).toHaveLength(0);
    });
});
