import { Mesh } from '../../../../src/scene/mesh.js';
import { WorldClustersDebug } from '../../../../src/scene/lighting/world-clusters-debug.js';

/**
 * Creates a stand-in for the WorldClusters instance consumed by WorldClustersDebug#render.
 */
const createWorldClusters = ({
    cells = [1, 1, 1],
    boundsMin = [0, 0, 0],
    boundsDelta = [2, 2, 2],
    counts = null,
    maxCellLightCount = 4
} = {}) => {
    const cellCount = new Vec3(cells[0], cells[1], cells[2]);
    const numCells = cells[0] * cells[1] * cells[2];
    return {
        cells: cellCount,
        _cells: cellCount,
        lightsBuffer: {
            boundsMin: new Vec3(boundsMin[0], boundsMin[1], boundsMin[2]),
            boundsDelta: new Vec3(boundsDelta[0], boundsDelta[1], boundsDelta[2])
        },
        counts: counts ?? new Array(numCells).fill(0),
        _maxCellLightCount: maxCellLightCount
    };
};

/**
 * Creates a stand-in for the Scene, recording the line arrays it is asked to draw. The arrays are
 * reused and emptied by the debug object, so copies are kept.
 */
const createScene = (device) => {
    const layer = { name: 'defaultDrawLayer' };
    const lineArrays = [];
    const drawLineArrays = jest.fn((positions, colors) => {
        lineArrays.push({
            positions: Array.from(positions),
            colors: Array.from(colors)
        });
    });
    return {
