            const [{ positions, colors }] = scene.lineArrays;

            // 3x4 lines in the x/z plane, 3x2 in the x/y plane and 2x4 in the y/z plane,
            // each line being two vertices of three components
            expect(positions).toHaveLength((3 * 4 + 3 * 2 + 2 * 4) * 2 * 3);
            expect(colors).toHaveLength((3 * 4 + 3 * 2 + 2 * 4) * 2 * 4);

            // the drawn arrays are the buffers owned by the debug object, emptied after use
            expect(scene.drawLineArrays.mock.calls[0][0]).toBe(debug.gridPositions);
            expect(scene.drawLineArrays.mock.calls[0][1]).toBe(debug.gridColors);
            expect(debug.gridPositions).toHaveLength(0);

            // x/z plane lines span the y range of the volume
            expect(positions.slice(0, 6)).toEqual([0, 0, 0, 0, 4, 0]);
            expect(positions.slice(30, 36)).toEqual([6, 0, 6, 6, 4, 6]);

            // x/y plane lines span the z range of the volume
            expect(positions.slice(72, 78)).toEqual([0, 0, 0, 0, 0, 6]);
            expect(positions.slice(102, 108)).toEqual([6, 4, 0, 6, 4, 6]);

            // y/z plane lines span the x range of the volume
            expect(positions.slice(108, 114)).toEqual([0, 0, 0, 6, 0, 0]);
            expect(positions.slice(150, 156)).toEqual([0, 4, 6, 6, 4, 6]);
        });

        it('places the grid on the light volume bounds', () => {
