                cells: [1, 1, 1],
                boundsMin: [10, -2, 5],
                boundsDelta: [2, 2, 2]
            });

            debug.render(worldClusters, scene);

            const [{ positions }] = scene.lineArrays;
            expect(positions).toEqual([
                10, -2, 5, 10, 0, 5,
                10, -2, 7, 10, 0, 7,
                12, -2, 5, 12, 0, 5,
                12, -2, 7, 12, 0, 7,

                10, -2, 5, 10, -2, 7,
                10, 0, 5, 10, 0, 7,
                12, -2, 5, 12, -2, 7,
                12, 0, 5, 12, 0, 7,

                10, -2, 5, 12, -2, 5,
                10, -2, 7, 12, -2, 7,
                10, 0, 5, 12, 0, 5,
                10, 0, 7, 12, 0, 7
            ]);
        });

        it('uses the debug grid color for the vertices', () => {
            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();
            const worldClusters = createWorldClusters({
                cells: [1, 1, 1],
