            }
        });

        it('keeps the existing grid colors when the vertex count does not change', () => {
            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();

            // colors already sized for the 24 grid vertices of a 1x1x1 cell grid
            const preexisting = new Array(24 * 4).fill(1.5);
            debug.gridColors = preexisting;

            debug.render(createWorldClusters({ cells: [1, 1, 1] }), scene);

            const [{ colors }] = scene.lineArrays;
            expect(debug.gridColors).toBe(preexisting);
            expect(colors).toHaveLength(24 * 4);
            expect(colors).toEqual(new Array(24 * 4).fill(1.5));
