            const debug = new WorldClustersDebug();

            // colors left over from an older, smaller grid
            debug.gridColors = [1.5, 1.5, 1.5, 1.5];

            debug.render(createWorldClusters({ cells: [1, 1, 1] }), scene);
            debug.render(createWorldClusters({ cells: [2, 2, 2] }), scene);

            expect(scene.drawLineArrays).toHaveBeenCalledTimes(2);

            const first = scene.lineArrays[0];
            expect(first.colors).toHaveLength(24 * 4);
            expect(first.colors.every(value => value !== 1.5)).toBe(true);
            expect(first.colors[0]).toBeCloseTo(0.3, 5);

            // 3x3 + 3x3 + 3x3 lines of two vertices each
            const second = scene.lineArrays[1];
            expect(second.positions).toHaveLength(27 * 2 * 3);
            expect(second.colors).toHaveLength(27 * 2 * 4);
            expect(second.colors.every(value => value !== 1.5)).toBe(true);
            expect(second.colors[0]).toBeCloseTo(0.3, 5);
        });
    });

    describe('cell occupancy mesh', () => {

        it('creates the occupancy mesh but no mesh instance when no cell is occupied', () => {
            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();

            debug.render(createWorldClusters({ cells: [2, 2, 2] }), scene);

            expect(debug.mesh).toBeInstanceOf(Mesh);
            expect(debug.meshInstance).toBeNull();
            expect(debug._pendingMeshInstance).toBeNull();
            expect(debug._layer).toBeNull();
        });

        it('builds a cube per occupied cell using the cluster index layout', () => {
            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();

            // cluster index = x + divX * (z + y * divZ), divX = 2, divZ = 2
            const counts = new Array(8).fill(0);
            counts[6] = 2;      // x = 0, z = 1, y = 1
            counts[1] = 1;      // x = 1, z = 0, y = 0
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsMin: [0, 0, 0],
                boundsDelta: [8, 8, 8],
                counts,
                maxCellLightCount: 4
            }), scene);

            const mesh = debug.mesh;
            expect(mesh).toBeInstanceOf(Mesh);

            const positions = new Float32Array(16 * 3);
            expect(mesh.getPositions(positions)).toBe(16);
            expect(Array.from(positions)).toEqual([
                // cell x = 0, z = 1, y = 1
                0, 4, 8, 4, 4, 8, 4, 8, 8, 0, 8, 8,
                4, 4, 4, 0, 4, 4, 0, 8, 4, 4, 8, 4,

                // cell x = 1, z = 0, y = 0
                4, 0, 4, 8, 0, 4, 8, 4, 4, 4, 4, 4,
                8, 0, 0, 4, 0, 0, 4, 4, 0, 8, 4, 0
            ]);

            const indices = new Uint16Array(2 * 36);
            expect(mesh.getIndices(indices)).toBe(2 * 36);
            expect(Array.from(indices)).toEqual([
                // first cube
                0, 1, 3, 3, 1, 2, 4, 5, 7, 7, 5, 6, 3, 2, 6, 2, 7, 6,
                1, 0, 4, 0, 5, 4, 1, 4, 2, 4, 7, 2, 5, 0, 6, 0, 3, 6,

                // second cube
                8, 9, 11, 11, 9, 10, 12, 13, 15, 15, 13, 14, 11, 10, 14, 10, 15, 14,
                9, 8, 12, 8, 13, 12, 9, 12, 10, 12, 15, 10, 13, 8, 14, 8, 11, 14
            ]);

            expect(mesh.primitive[0].type).toBe(PRIMITIVE_TRIANGLES);
            expect(mesh.primitive[0].count).toBe(72);
            expect(mesh.primitive[0].indexed).toBe(true);
        });

        it('colors each cube from the occupancy ratio between the low and high colors', () => {
            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();

            const counts = new Array(8).fill(0);
            counts[0] = 1;      // quarter of the limit
            counts[7] = 4;      // fully saturated
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsDelta: [8, 8, 8],
                counts,
                maxCellLightCount: 4
            }), scene);

