            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();

            const counts = new Array(8).fill(0);
            counts[0] = 1;
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsDelta: [8, 8, 8],
                counts
            }), scene);

            const instance = debug.meshInstance;
            expect(instance).not.toBeNull();
            expect(instance.mesh).toBe(debug.mesh);
            expect(instance.node.name).toBe('WorldClustersDebug');
            expect(instance.cull).toBe(false);
            expect(instance.castShadow).toBe(false);

