            expect(material.useLighting).toBe(false);
            expect(material.emissiveVertexColor).toBe(true);
            expect(material.blendType).toBe(BLEND_ADDITIVEALPHA);
            expect(material.depthWrite).toBe(false);
            expect(material.emissive.r).toBe(1);
            expect(material.emissive.g).toBe(1);
            expect(material.emissive.b).toBe(1);

            // the instance is handed to the layer the debug data belongs to
            expect(debug._pendingMeshInstance).toBe(instance);
            expect(debug._layer).toBe(scene.defaultDrawLayer);
        });

        it('reuses the mesh and mesh instance on later renders', () => {
            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();

            const counts = new Array(8).fill(0);
            counts[0] = 1;
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsDelta: [8, 8, 8],
                counts
            }), scene);

            const mesh = debug.mesh;
            const instance = debug.meshInstance;
            expect(mesh.vertexBuffer.numVertices).toBe(8);

            const counts2 = new Array(8).fill(0);
            counts2[0] = 1;
            counts2[1] = 1;
            counts2[2] = 1;
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsDelta: [8, 8, 8],
                counts: counts2
            }), scene);

            expect(debug.mesh).toBe(mesh);
            expect(debug.meshInstance).toBe(instance);
            expect(mesh.vertexBuffer.numVertices).toBe(24);
            expect(mesh.primitive[0].count).toBe(3 * 36);
            expect(debug._pendingMeshInstance).toBe(instance);
            expect(debug._layer).toBe(scene.defaultDrawLayer);
        });

        it('drops the pending mesh instance when the new frame has no occupied cells', () => {
            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();

            const counts = new Array(8).fill(0);
            counts[0] = 1;
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsDelta: [8, 8, 8],
                counts
            }), scene);

            const instance = debug.meshInstance;
            expect(debug._pendingMeshInstance).toBe(instance);

            // next frame, no cell holds any light
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsDelta: [8, 8, 8],
                counts: new Array(8).fill(0)
            }), scene);

            expect(debug._pendingMeshInstance).toBeNull();
            expect(debug._layer).toBeNull();

            // the mesh instance is kept for a later frame
            expect(debug.meshInstance).toBe(instance);
        });

        it('updates an existing pending mesh instance instead of creating a new one', () => {
            const device = new NullGraphicsDevice();
            const scene = createScene(device);
            const debug = new WorldClustersDebug();

            const counts = new Array(8).fill(0);
            counts[3] = 2;
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsDelta: [8, 8, 8],
                counts
            }), scene);
            const instance = debug.meshInstance;

            counts[3] = 3;
            debug.render(createWorldClusters({
                cells: [2, 2, 2],
                boundsDelta: [8, 8, 8],
                counts
            }), scene);

            expect(debug.meshInstance).toBe(instance);
            expect(debug._pendingMeshInstance).toBe(instance);

            // a single cube was rebuilt, re-using the same mesh
            expect(instance.mesh.vertexBuffer.numVertices).toBe(8);
            expect(instance.mesh.primitive[0].count).toBe(36);
