import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';

import { Mat4 } from '../../../../src/core/math/mat4.js';
import { Vec3 } from '../../../../src/core/math/vec3.js';
import { ParticleCPUUpdater } from '../../../../src/scene/particle-system/cpu-updater.js';

function createNode({ worldTransform = new Mat4(), localScale = new Vec3(1, 1, 1), position = new Vec3() } = {}) {
    return {
        worldTransform,
        localScale,
        getPosition: () => position
    };
}

function channel(value) {
    return [0, 0, value, 0, 0];
}

function vectorChannel(x, y, z) {
    const values = new Array(9).fill(0);
    values[6] = x;
    values[7] = y;
    values[8] = z;
    return values;
}

function createEmitter(overrides = {}) {
    return Object.assign({
        meshInstance: {
            node: createNode()
        },
        localSpace: true,
        camera: null,
        useMesh: false,
        numParticles: 1,
        numParticleVerts: 1,
        numParticlesPot: 4,
        precision: 5,
        lifetime: 4,
        rate: 1,
        rate2: 1,
        loop: false,
        initialVelocity: 0,
        emitterShape: 0,
        alignToMotion: false,
        wrap: false,
        wrapBounds: null,
        sort: 0,
        particleDistance: new Float32Array(8),
        vbCPU: new Float32Array([10, 11, 12, 0]),
        vbOld: new Float32Array(4),
        qRotSpeed: channel(4),
        qRotSpeed2: channel(4),
        qScale: channel(2),
        qScale2: channel(2),
        qAlpha: channel(0.5),
        qAlpha2: channel(0.5),
        qRadialSpeed: channel(2),
        qRadialSpeed2: channel(2),
        qLocalVelocity: vectorChannel(1, 2, 3),
        qLocalVelocity2: vectorChannel(1, 2, 3),
        qVelocity: vectorChannel(10, 20, 30),
        qVelocity2: vectorChannel(10, 20, 30)
    }, overrides);
}

function createParticleTex(emitter) {
    return new Float32Array(emitter.numParticlesPot * 12);
}

function setParticle(emitter, particleTex, id, {
    position = [0, 0, 0],
    rotation = 0,
    life = 1,
    randomFactors = [0, 0, 0],
    visible = 0
} = {}) {
    const stride = emitter.numParticlesPot * 4;
    const randomOffset = emitter.numParticlesPot * 8;
    particleTex[id * 4] = position[0];
    particleTex[id * 4 + 1] = position[1];
    particleTex[id * 4 + 2] = position[2];
    particleTex[id * 4 + 3] = rotation;
    particleTex[id * 4 + 3 + stride] = life;
    particleTex[id * 4 + randomOffset] = randomFactors[0];
    particleTex[id * 4 + 1 + randomOffset] = randomFactors[1];
    particleTex[id * 4 + 2 + randomOffset] = randomFactors[2];
    particleTex[id * 4 + 3 + randomOffset] = visible;
}

function disableMotion(emitter) {
    emitter.qRotSpeed = channel(0);
    emitter.qRotSpeed2 = channel(0);
    emitter.qScale = channel(0);
    emitter.qScale2 = channel(0);
    emitter.qAlpha = channel(0);
    emitter.qAlpha2 = channel(0);
    emitter.qRadialSpeed = channel(0);
    emitter.qRadialSpeed2 = channel(0);
    emitter.qLocalVelocity = vectorChannel(0, 0, 0);
    emitter.qLocalVelocity2 = vectorChannel(0, 0, 0);
    emitter.qVelocity = vectorChannel(0, 0, 0);
    emitter.qVelocity2 = vectorChannel(0, 0, 0);
}

