            return renderData[face];
        })
    };

    return { light, renderData };
}

function createMeshInstance({
    center = new Vec3(0, 0, 0),
    halfExtents = new Vec3(0.5, 0.5, 0.5),
    castShadow = true,
    visible = true,
    cull = true,
    isVisibleFunc = null,
    isVisible = () => false
} = {}) {
    const aabb = new BoundingBox(center, halfExtents);
    const aabbGetter = jest.fn(() => aabb);

    return {
        castShadow,
        visible,
        cull,
        isVisibleFunc,
        visibleThisFrame: false,
        _aabb: aabb,
        get aabb() {
            return aabbGetter();
        },
        aabbGetter,
        _isVisible: jest.fn(isVisible)
    };
}

function createSubject({ withScene = true } = {}) {
    const sorter = {
        sortMaterialMesh: jest.fn()
    };
