            const emitter = createEmitter({
                preWarm: true,
                lifetime: 1,
                numParticles: 2,
                initialVelocity: 0
            });

            // prewarming advances the simulation by a whole lifetime
            expect(emitter.simTimeTotal).toBeCloseTo(1);
        });

