        it('creates GPU simulation textures and render targets', () => {
            const emitter = createEmitter({ numParticles: 5 }, { gpuParticles: true });

            expect(emitter.numParticlesPot).toBe(8);
            expect(emitter.particleTexIN).not.toBe(emitter.particleTexOUT);

            for (const texture of [emitter.particleTexIN, emitter.particleTexOUT, emitter.particleTexStart]) {
                expect(texture.width).toBe(8);
                expect(texture.height).toBe(2);
                expect(texture.format).toBe(PIXELFORMAT_RGBA32F);
            }

            expect(emitter.rtParticleTexIN.colorBuffer).toBe(emitter.particleTexIN);
            expect(emitter.rtParticleTexOUT.colorBuffer).toBe(emitter.particleTexOUT);
            expect(emitter.rtParticleTexIN.depth).toBe(false);
            expect(emitter.rtParticleTexOUT.depth).toBe(false);
        });

        it('uses RGBA32U textures and uvec4 shader outputs when float textures are not renderable', () => {
            const emitter = createEmitter({ numParticles: 2 }, {
                gpuParticles: true,
                textureFloatRenderable: false
            });

            expect(emitter.particleTexIN.format).toBe(PIXELFORMAT_RGBA32U);
            expect(emitter.particleTexOUT.format).toBe(PIXELFORMAT_RGBA32U);
            expect(emitter.shaderParticleUpdateRespawn.definition.fshader).toContain('#define outType_0 uvec4');
        });

        it('uses RGBA32F textures and vec4 shader outputs when float textures are renderable', () => {
            const emitter = createEmitter({ numParticles: 2 }, { gpuParticles: true });

            expect(emitter.particleTexIN.format).toBe(PIXELFORMAT_RGBA32F);
            expect(emitter.shaderParticleUpdateRespawn.definition.fshader).toContain('#define outType_0 vec4');
        });

        it('creates the internal simulation lookup textures for GPU particles', () => {
            const emitter = createEmitter({}, { gpuParticles: true });

            for (const name of ['internalTex0', 'internalTex1', 'internalTex2', 'internalTex3']) {
                expect(emitter[name]).not.toBeNull();
                expect(emitter.material.getParameter(name).data).toBe(emitter[name]);
            }

            expect(emitter.colorParam).not.toBeNull();
            expect(emitter.material.getParameter('colorParam').data).toBe(emitter.colorParam);
        });

        it('destroys the previous textures and resources on rebuild', () => {
            const emitter = createEmitter({ numParticles: 2 }, { gpuParticles: true });

            const oldIn = emitter.particleTexIN;
            const oldOut = emitter.particleTexOUT;
            const oldColorParam = emitter.colorParam;
            const oldMeshInstance = emitter.meshInstance;
            const oldVertexBuffer = emitter.vertexBuffer;

            emitter.rebuild();

            // a destroyed texture is detached from its device
            expect(oldIn.device).toBeNull();
            expect(oldOut.device).toBeNull();
            expect(oldColorParam.device).toBeNull();

            expect(emitter.particleTexIN).not.toBe(oldIn);
            expect(emitter.particleTexOUT).not.toBe(oldOut);
            expect(emitter.colorParam).not.toBe(oldColorParam);
            expect(emitter.meshInstance).not.toBe(oldMeshInstance);
            expect(emitter.vertexBuffer).not.toBe(oldVertexBuffer);
        });
