            expect(emitter.shaderParticleUpdateRespawn).not.toBeNull();
            expect(emitter.shaderParticleUpdateNoRespawn).not.toBeNull();
            expect(emitter.shaderParticleUpdateOnStop).not.toBeNull();

            expect(emitter.shaderParticleUpdateRespawn.name).toBe('ParticleUpdateRespawn-Shape:0-Local:false');
            expect(emitter.shaderParticleUpdateNoRespawn.name).toBe('ParticleUpdateNoRespawn-Shape:0-Local:false');
            expect(emitter.shaderParticleUpdateOnStop.name).toBe('ParticleUpdateStop-Shape:0-Local:false');
