            expect(respawn).not.toContain('#define NO_RESPAWN');
            expect(respawn).not.toContain('#define ON_STOP');

            expect(noRespawn).toContain('#define NO_RESPAWN');
            expect(noRespawn).not.toContain('#define RESPAWN');
            expect(noRespawn).not.toContain('#define ON_STOP');

            expect(onStop).toContain('#define ON_STOP');
            expect(onStop).not.toContain('#define RESPAWN');
            expect(onStop).not.toContain('#define NO_RESPAWN');
