    it('defines useMesh from the supplied mesh', () => {
        const emitter = createEmitter();
        expect(emitter.useMesh).toBe(false);

        const device = createDevice();
        const withMesh = createEmitter({ mesh: createQuadMesh(device) });
        expect(withMesh.useMesh).toBe(true);
    });

    it('forces CPU particles when sorting is enabled', () => {
        const emitter = createEmitter({ sort: PARTICLESORT_DISTANCE }, { gpuParticles: true });

        expect(emitter.sort).toBeGreaterThan(PARTICLESORT_NONE);
        expect(emitter.useCpu).toBe(true);
        expect(emitter.particleTexIN).toBeNull();
        expect(emitter.particleTexOUT).toBeNull();
    });

    it('forces CPU particles when the device requests it', () => {
        const emitter = createEmitter({}, { gpuParticles: true, forceCpuParticles: true });

        expect(emitter.useCpu).toBe(true);
        expect(emitter.particleTexIN).toBeNull();
    });

    it('keeps using the CPU once a rebuild has switched to it', () => {
        const emitter = createEmitter({ sort: PARTICLESORT_DISTANCE }, { gpuParticles: true });
        expect(emitter.useCpu).toBe(true);

        emitter.sort = PARTICLESORT_NONE;
        emitter.rebuild();

        expect(emitter.useCpu).toBe(true);
    });

    it('uses GPU particles when the device supports them and sorting is off', () => {
        const emitter = createEmitter({}, { gpuParticles: true });

        expect(emitter.useCpu).toBe(false);
        expect(emitter.particleTexIN).not.toBeNull();
    });

    it('rounds the particle count up to a power of two', () => {
        expect(createEmitter({ numParticles: 1 }).numParticlesPot).toBe(1);
        expect(createEmitter({ numParticles: 2 }).numParticlesPot).toBe(2);
        expect(createEmitter({ numParticles: 3 }).numParticlesPot).toBe(4);
        expect(createEmitter({ numParticles: 5 }).numParticlesPot).toBe(8);
        expect(createEmitter({ numParticles: 16 }).numParticlesPot).toBe(16);
    });
});

describe('bounds', () => {

    it('computes local bounds enclosing the box spawn volume and the particle size', () => {
        const extents = new Vec3(2, 4, 6);
        const emitter = createEmitter({ emitterExtents: extents });

        // the default 1.0 scale curve grows the bounds by one unit in every direction
        expect(emitter.localBounds.halfExtents.x).toBeCloseTo(1 + 1);
        expect(emitter.localBounds.halfExtents.y).toBeCloseTo(2 + 1);
        expect(emitter.localBounds.halfExtents.z).toBeCloseTo(3 + 1);

        // the spawn volume the bounds were computed for is remembered
        expect(emitter.prevEmitterExtents.equals(extents)).toBe(true);
        expect(emitter.prevEmitterRadius).toBe(0);
    });

    it('takes the particle scale graph into account for local bounds', () => {
        const emitter = createEmitter({
            emitterExtents: new Vec3(2, 2, 2),
            scaleGraph: new Curve([0, 3, 1, 3])
        });

        expect(emitter.localBounds.halfExtents.x).toBeCloseTo(1 + 3);
        expect(emitter.localBounds.halfExtents.y).toBeCloseTo(1 + 3);
        expect(emitter.localBounds.halfExtents.z).toBeCloseTo(1 + 3);
    });

    it('computes local bounds from the emitter radius for sphere emitters', () => {
        const emitter = createEmitter({
            emitterShape: EMITTERSHAPE_SPHERE,
            emitterRadius: 2
        });

        expect(emitter.localBounds.halfExtents.x).toBeCloseTo(2 + 1);
        expect(emitter.localBounds.halfExtents.y).toBeCloseTo(2 + 1);
        expect(emitter.localBounds.halfExtents.z).toBeCloseTo(2 + 1);
        expect(emitter.prevEmitterRadius).toBe(2);
    });

    it('transforms the world bounds by the node transform', () => {
        const node = new GraphNode('emitter');
        node.setPosition(10, 20, 30);
        const emitter = createEmitter({ emitterExtents: new Vec3(2, 4, 6) }, {}, node);

        expect(emitter.worldBounds.center.x).toBeCloseTo(10);
        expect(emitter.worldBounds.center.y).toBeCloseTo(20);
        expect(emitter.worldBounds.center.z).toBeCloseTo(30);
        expect(emitter.worldBounds.halfExtents.x).toBeCloseTo(2);
        expect(emitter.worldBounds.halfExtents.y).toBeCloseTo(3);
        expect(emitter.worldBounds.halfExtents.z).toBeCloseTo(4);

        // the trail bounds used by the softening pass start as copies of the world bounds
        for (const trail of emitter.worldBoundsTrail) {
            expect(trail.center.equals(emitter.worldBounds.center)).toBe(true);
            expect(trail.halfExtents.equals(emitter.worldBounds.halfExtents)).toBe(true);
        }

        // not in local space, the mesh instance bounds are the world bounds
        expect(emitter.meshInstance.aabb.center.equals(emitter.worldBounds.center)).toBe(true);
        expect(emitter.meshInstance.aabb.halfExtents.equals(emitter.worldBounds.halfExtents)).toBe(true);
    });

    it('keeps the world bounds in local space when localSpace is enabled', () => {
        const node = new GraphNode('emitter');
        node.setPosition(10, 20, 30);
        const emitter = createEmitter({ localSpace: true, emitterExtents: new Vec3(2, 4, 6) }, {}, node);

        expect(emitter.worldBounds.center.x).toBeCloseTo(0);
        expect(emitter.worldBounds.center.y).toBeCloseTo(0);
        expect(emitter.worldBounds.center.z).toBeCloseTo(0);
        expect(emitter.worldBounds.halfExtents.equals(emitter.localBounds.halfExtents)).toBe(true);

        // the mesh instance bounds are still placed in the world
        expect(emitter.meshInstance.aabb.center.x).toBeCloseTo(10);
        expect(emitter.meshInstance.aabb.center.y).toBeCloseTo(20);
        expect(emitter.meshInstance.aabb.center.z).toBeCloseTo(30);
    });
});

